#!/usr/bin/env python3
"""pasang_antarmuka.py - memasang antarmuka web ke ~/projects/antarmuka/.

    python3 pasang_antarmuka.py

    antarmuka/backend/    app.py (server FastAPI), layanan.py (logika), pratinjau_kalibrasi.py, jalankan.sh
    antarmuka/frontend/   index.html, gaya.css, aplikasi.js  (4 halaman: Pengambilan video, Kalibrasi, Proses, Hasil)
    antarmuka/node/       node_kamera.py  (program untuk Raspberry Pi)
    antarmuka/data/       setelan.json (jadwal, daftar node, token) dan profil kalibrasi tiap node - dibuat saat server jalan

Satu perubahan pada pipeline: config.py di uji_session0_pipeline ditambah blok di akhir berkas agar bisa
membaca profil kamera per node (cadangan: config.py.sebelum_profil). Tanpa antarmuka, pipeline berjalan seperti biasa.
Susunan lama (app.py dan web/ langsung di antarmuka/) dipindah ke antarmuka/_lama/.
"""
import json, os, shutil, sys

PROYEK = os.path.expanduser("~/projects")
TUJUAN = os.path.join(PROYEK, "antarmuka")
PIPELINE = os.path.join(PROYEK, "uji_session0_pipeline")
BERKAS = json.loads(r'''{"backend/app.py": "\"\"\"\napp.py - server FastAPI untuk antarmuka web pipeline deteksi dan penghitungan kendaraan.\n\nJalankan dengan ./jalankan.sh, lalu buka http://127.0.0.1:8000 di peramban.\nSemua logika ada di layanan.py; berkas ini hanya memetakan alamat web ke fungsi di sana.\nHalaman web (HTML/CSS/JS) ada di ../frontend dan disajikan oleh server ini.\n\nKeamanan: halaman web dan API-nya hanya melayani komputer ini sendiri (127.0.0.1).\nDari jaringan, yang dilayani hanya alamat /api/node/... milik Raspberry Pi, dan itu wajib membawa token.\n\"\"\"\n\nimport os\nfrom contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI, File, Form, Header, HTTPException, Request, UploadFile\nfrom fastapi.responses import FileResponse, JSONResponse, Response\nfrom fastapi.staticfiles import StaticFiles\n\nimport layanan\n\nFRONTEND = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), \"frontend\")\nLOKAL = (\"127.0.0.1\", \"::1\", \"localhost\")\n\n\n@asynccontextmanager\nasync def _siklus(_app):\n    layanan.muat_dari_disk()      # baca riwayat pekerjaan saat server mulai\n    yield\n\n\napp = FastAPI(title=\"Penghitung Kendaraan 3D\", lifespan=_siklus)\n\n\n@app.middleware(\"http\")\nasync def _hanya_lokal(request: Request, call_next):\n    asal = request.client.host if request.client else \"\"\n    if asal not in LOKAL and not request.url.path.startswith(\"/api/node/\"):\n        return JSONResponse({\"detail\": \"Halaman ini hanya bisa dibuka dari komputer server.\"}, status_code=403)\n    return await call_next(request)\n\n\n@app.exception_handler(layanan.Salah)\nasync def _masukan_salah(_request, exc):\n    return JSONResponse({\"detail\": str(exc)}, status_code=400)\n\n\ndef _cek_token(token):\n    if not layanan.token_sah(token):\n        raise HTTPException(status_code=401, detail=\"Token node salah.\")\n\n\n# ---------------------------------------------------------------- umum\n@app.get(\"/api/info\")\ndef info():\n    return layanan.info()\n\n\n# ---------------------------------------------------------------- kalibrasi (profil kamera)\n@app.get(\"/api/kamera/{node_id}/profil\")\ndef profil(node_id: str):\n    return layanan.profil(node_id)\n\n\nasync def _formulir(request: Request):\n    \"\"\"Formulir multipart -> (dict nilai teks, isi berkas 'xml' atau None).\"\"\"\n    form = await request.form()\n    data, xml = {}, None\n    for k, v in form.items():\n        if hasattr(v, \"read\"):\n            if k == \"xml\" and getattr(v, \"filename\", \"\"):\n                xml = await v.read()\n        else:\n            data[k] = v\n    return data, xml\n\n\n@app.post(\"/api/kamera/{node_id}/profil\")\nasync def simpan_profil(node_id: str, request: Request):\n    data, xml = await _formulir(request)\n    return layanan.simpan_profil(node_id, data, xml)\n\n\n@app.post(\"/api/kamera/{node_id}/pratinjau\")\nasync def pratinjau(node_id: str, request: Request):\n    data, xml = await _formulir(request)\n    gambar = layanan.pratinjau(node_id, data, data.get(\"sumber\", \"\"), data.get(\"posisi\", 0.5), xml)\n    return Response(content=gambar, media_type=\"image/jpeg\")\n\n\n# ---------------------------------------------------------------- pengambilan video\n@app.get(\"/api/rekaman\")\ndef rekaman(node: str = \"\"):\n    return layanan.daftar_rekaman(node or None)\n\n\n@app.post(\"/api/rekaman\")\ndef unggah_manual(node: str = Form(...), berkas: UploadFile = File(...)):\n    return {\"sumber\": layanan.simpan_rekaman(node, berkas.file, \"manual\", berkas.filename)}\n\n\n@app.delete(\"/api/rekaman\")\ndef hapus_rekaman(sumber: str):\n    layanan.hapus_rekaman(sumber)\n    return {\"ok\": True}\n\n\n@app.post(\"/api/kamera/{node_id}/rekam\")\ndef minta_rekam(node_id: str, durasi: str = Form(...)):\n    return layanan.minta_rekam(node_id, durasi)\n\n\n@app.get(\"/api/permintaan\")\ndef permintaan(node: str = \"\"):\n    return layanan.daftar_permintaan(node or None)\n\n\n# ---------------------------------------------------------------- untuk Raspberry Pi (wajib token)\n@app.get(\"/api/node/{node_id}/tugas\")\ndef node_tugas(node_id: str, x_token: str = Header(\"\")):\n    _cek_token(x_token)\n    return layanan.node_tugas(node_id)\n\n\n@app.post(\"/api/node/{node_id}/rekaman\")\ndef node_unggah(node_id: str, berkas: UploadFile = File(...), mode: str = Form(...), slot: str = Form(\"\"),\n                id_permintaan: str = Form(\"\"), x_token: str = Header(\"\")):\n    _cek_token(x_token)\n    return layanan.node_unggah(node_id, berkas.file, mode, slot, id_permintaan, berkas.filename or \"rekaman.mp4\")\n\n\n# ---------------------------------------------------------------- proses dan hasil\n@app.get(\"/api/jobs\")\ndef daftar():\n    return layanan.daftar_job()\n\n\n@app.post(\"/api/jobs\")\ndef buat(sumber: str = Form(...), node: str = Form(...), model: str = Form(\"\"), conf: str = Form(\"\"),\n         conf_low: str = Form(\"\")):\n    return layanan.buat_job(sumber, node, model or None, conf, conf_low)\n\n\n@app.get(\"/api/jobs/{job_id}\")\ndef satu(job_id: str):\n    st = layanan.ambil_job(job_id)\n    if st is None:\n        raise HTTPException(status_code=404, detail=\"Pekerjaan tidak ditemukan.\")\n    return st\n\n\n@app.delete(\"/api/jobs/{job_id}\")\ndef hapus(job_id: str):\n    hasil = layanan.hapus_job(job_id)\n    if hasil == \"tidak ada\":\n        raise HTTPException(status_code=404, detail=\"Pekerjaan tidak ditemukan.\")\n    if hasil == \"sedang berjalan\":\n        raise HTTPException(status_code=409, detail=\"Pekerjaan masih berjalan.\")\n    return {\"ok\": True}\n\n\n@app.get(\"/api/jobs/{job_id}/berkas/{nama}\")\ndef berkas_hasil(job_id: str, nama: str):\n    p = layanan.jalur_berkas(job_id, nama)\n    if p is None:\n        raise HTTPException(status_code=404, detail=\"Berkas tidak ada.\")\n    jenis = {\"hasil.mp4\": \"video/mp4\", \"counting_log.csv\": \"text/csv\", \"keluaran.txt\": \"text/plain\"}[nama]\n    return FileResponse(p, media_type=jenis, filename=None if nama == \"hasil.mp4\" else nama)\n\n\n# halaman web (harus terakhir agar tidak menutupi /api)\napp.mount(\"/\", StaticFiles(directory=FRONTEND, html=True), name=\"web\")\n", "backend/layanan.py": "\"\"\"\nlayanan.py - logika antarmuka. Tidak bergantung pada FastAPI, sehingga bisa diuji sendiri.\n\nBagian:\n  1. Setelan server        data/setelan.json (jadwal otomatis, daftar node, token node) - diubah dengan tangan\n  2. Profil kamera         data/kamera/<node>.json - kalibrasi dan garis hitung per node (halaman Kalibrasi)\n  3. Rekaman               ~/projects/video_rekaman/<node>/<tanggal>_<jam>_<mode>.mp4\n  4. Node (Raspberry Pi)   node menanyakan tugas, merekam, lalu mengunggah (lihat ../node/node_kamera.py)\n  5. Pekerjaan (job)       satu video diproses run.py; satu per satu (antrean)\n  6. Ringkasan hasil       dari counting_log.csv\n\nFolder tiap job: ~/projects/hasil/antarmuka/<id>/  (status.json, hasil.mp4, counting_log.csv, ringkasan.json, keluaran.txt)\n\"\"\"\n\nimport csv\nimport hmac\nimport importlib.util\nimport json\nimport os\nimport queue\nimport re\nimport secrets\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport threading\nimport time\n\nPROYEK = os.path.expanduser(os.environ.get(\"ANTARMUKA_PROYEK\", \"~/projects\"))\nPIPELINE = os.environ.get(\"ANTARMUKA_PIPELINE\", os.path.join(PROYEK, \"uji_session0_pipeline\"))\nANTARMUKA = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nDATA_APP = os.environ.get(\"ANTARMUKA_DATA\", os.path.join(ANTARMUKA, \"data\"))\nDATA = os.path.join(PROYEK, \"hasil\", \"antarmuka\")          # hasil tiap job\nVIDEO_DIR = os.path.join(PROYEK, \"video_uji\")              # video contoh\nREKAMAN = os.path.join(PROYEK, \"video_rekaman\")            # rekaman dari node\nMODEL_DIR = os.path.join(PROYEK, \"bobot\", \"detektor\")\nMODEL_BAWAAN = \"centernet_dari_baru.pth\"\nPYTHON = sys.executable\nEKSTENSI = (\".mp4\", \".avi\", \".mov\", \".mkv\")\nMAKS_UNGGAH = 500 * 1024 * 1024\nCACHE_KHUSUS = {(\"uji_val_720p.mp4\", MODEL_BAWAAN): \"det_session0.pkl\"}   # cache deteksi yang sudah ada\nID_SAH = re.compile(r\"^\\d{8}-\\d{6}-[0-9a-f]{4}$\")\nNODE_SAH = re.compile(r\"^[A-Za-z0-9_\\-]{1,40}$\")\nNAMA_REKAMAN = re.compile(r\"^(\\d{8})_(\\d{6})_(otomatis|manual)\\.mp4$\")\nPOLA_PROGRES = re.compile(rb\"(\\d+)/(\\d+) \\[\")\nKUNCI_PROFIL = (\"PITCH_DEG\", \"CAM_HEIGHT_M\", \"FOCAL_PX\", \"LANE_HALF_WIDTH_M\", \"MAX_TRACK_DEPTH_M\",\n                \"LINE_Y_DEFAULT_M\", \"LINE_Y_AWAY_M\", \"MEDIAN_X_M\")\nBATAS_PROFIL = {\"PITCH_DEG\": (0.0, 89.0), \"CAM_HEIGHT_M\": (1.0, 60.0), \"FOCAL_PX\": (100.0, 20000.0),\n                \"LANE_HALF_WIDTH_M\": (2.0, 60.0), \"MAX_TRACK_DEPTH_M\": (10.0, 400.0),\n                \"LINE_Y_DEFAULT_M\": (3.0, 300.0), \"LINE_Y_AWAY_M\": (3.0, 300.0), \"MEDIAN_X_M\": (-60.0, 60.0)}\n\n_kunci = threading.RLock()\n_jobs = {}                 # id -> status\n_antrean = queue.Queue()\n_pekerja = None\n_terlihat = {}             # node -> waktu terakhir node menghubungi server\n_permintaan = []           # permintaan rekam manual: {id, node, durasi_detik, status, dibuat}\n\n\ndef _muat_config():\n    \"\"\"config.py milik pipeline, TANPA profil kamera (nilai bawaan pipeline).\"\"\"\n    lama = os.environ.pop(\"PROFIL_KAMERA\", None)\n    try:\n        spec = importlib.util.spec_from_file_location(\"config_pipeline\", os.path.join(PIPELINE, \"config.py\"))\n        mod = importlib.util.module_from_spec(spec)\n        spec.loader.exec_module(mod)\n    finally:\n        if lama is not None:\n            os.environ[\"PROFIL_KAMERA\"] = lama\n    return mod\n\n\ncfg = _muat_config()\n\n\nclass Salah(ValueError):\n    \"\"\"Masukan tidak sah; pesannya ditampilkan ke pengguna.\"\"\"\n\n\ndef _tulis_json(path, obj):\n    os.makedirs(os.path.dirname(path), exist_ok=True)\n    tmp = path + \".tmp\"\n    with open(tmp, \"w\", encoding=\"utf-8\") as f:\n        json.dump(obj, f, ensure_ascii=False, indent=1)\n    os.replace(tmp, path)\n\n\ndef _baca_json(path, bawaan=None):\n    try:\n        with open(path, encoding=\"utf-8\") as f:\n            return json.load(f)\n    except (OSError, ValueError):\n        return bawaan\n\n\ndef _hex(bgr):\n    b, g, r = bgr\n    return \"#%02x%02x%02x\" % (r, g, b)\n\n\n# ====================================================================== 1. setelan server\ndef setelan():\n    \"\"\"Setelan tetap server. Dibuat sekali dengan nilai bawaan; ubah dengan menyunting berkasnya.\"\"\"\n    p = os.path.join(DATA_APP, \"setelan.json\")\n    s = _baca_json(p)\n    if s is None:\n        s = {\n            \"_keterangan\": \"Setelan tetap. Sunting berkas ini lalu mulai ulang server. Halaman web hanya menampilkan.\",\n            \"izinkan_jaringan\": False,\n            \"token_node\": secrets.token_hex(16),\n            \"jadwal\": {\"video_per_hari\": 6, \"durasi_detik\": 60, \"jam_mulai\": \"06:00\", \"jam_selesai\": \"18:00\"},\n            \"node\": [{\"id\": \"session0_right\", \"nama\": \"Latihan session0_right\"},\n                     {\"id\": \"kamera1\", \"nama\": \"Kamera 1 (Raspberry Pi)\"}],\n        }\n        _tulis_json(p, s)\n    return s\n\n\ndef _menit(jam):\n    h, m = jam.split(\":\")\n    return int(h) * 60 + int(m)\n\n\ndef jadwal_harian():\n    \"\"\"Daftar jam mulai rekaman otomatis ('HH:MM'), tersebar rata di antara jam_mulai dan jam_selesai.\"\"\"\n    j = setelan()[\"jadwal\"]\n    n = max(0, int(j[\"video_per_hari\"]))\n    a, b = _menit(j[\"jam_mulai\"]), _menit(j[\"jam_selesai\"])\n    if n == 0 or b <= a:\n        return []\n    return [\"%02d:%02d\" % divmod(int(a + i * (b - a) / n), 60) for i in range(n)]\n\n\ndef daftar_node():\n    out = []\n    for n in setelan()[\"node\"]:\n        t = _terlihat.get(n[\"id\"])\n        out.append({\"id\": n[\"id\"], \"nama\": n.get(\"nama\", n[\"id\"]),\n                    \"terhubung\": bool(t and time.time() - t < 20),\n                    \"terakhir\": time.strftime(\"%Y-%m-%d %H:%M:%S\", time.localtime(t)) if t else None,\n                    \"ada_profil\": os.path.exists(_jalur_profil(n[\"id\"]))})\n    return out\n\n\ndef _cek_node(node_id):\n    if not node_id or not NODE_SAH.match(node_id) or node_id not in [n[\"id\"] for n in setelan()[\"node\"]]:\n        raise Salah(\"Node tidak dikenal: %s (daftarkan di data/setelan.json).\" % node_id)\n    return node_id\n\n\ndef daftar_model():\n    if not os.path.isdir(MODEL_DIR):\n        return []\n    m = sorted(n for n in os.listdir(MODEL_DIR) if n.endswith(\".pth\"))\n    return sorted(m, key=lambda n: n != MODEL_BAWAAN)       # bawaan di depan\n\n\ndef daftar_contoh():\n    if not os.path.isdir(VIDEO_DIR):\n        return []\n    return sorted(n for n in os.listdir(VIDEO_DIR) if n.lower().endswith(EKSTENSI))\n\n\ndef info():\n    run_py = open(os.path.join(PIPELINE, \"run.py\"), encoding=\"utf-8\").read()\n    cfg_py = open(os.path.join(PIPELINE, \"config.py\"), encoding=\"utf-8\").read()\n    masalah = []\n    if '\"--out\"' not in run_py:\n        masalah.append(\"run.py belum bisa menyimpan video (jalankan alat/pasang_video.py di folder pipeline).\")\n    if \"PROFIL_KAMERA\" not in cfg_py:\n        masalah.append(\"config.py pipeline belum membaca profil kamera (jalankan ulang alat/pasang_antarmuka.py).\")\n    if not daftar_model():\n        masalah.append(\"Tidak ada bobot .pth di \" + MODEL_DIR)\n    if not shutil.which(\"ffmpeg\"):\n        masalah.append(\"ffmpeg belum terpasang; video hasil mungkin tidak bisa diputar di peramban (sudo apt install ffmpeg).\")\n    warna = getattr(cfg, \"CLASS_COLORS\", {})\n    s = setelan()\n    return {\n        \"kelas\": [{\"nama\": c, \"warna\": _hex(warna.get(c, (200, 200, 200)))} for c in cfg.CLASSES],\n        \"bawaan\": {\"conf\": 0.4, \"conf_low\": 0.2},\n        \"model\": daftar_model(),\n        \"contoh\": daftar_contoh(),\n        \"node\": daftar_node(),\n        \"jadwal\": dict(s[\"jadwal\"], jam=jadwal_harian()),\n        \"berkas_setelan\": os.path.join(DATA_APP, \"setelan.json\"),\n        \"masalah\": masalah,\n    }\n\n\n# ====================================================================== 2. profil kamera\ndef _jalur_profil(node_id):\n    return os.path.join(DATA_APP, \"kamera\", node_id + \".json\")\n\n\ndef _profil_bawaan():\n    p = {k: float(getattr(cfg, k)) for k in KUNCI_PROFIL if hasattr(cfg, k)}\n    p.setdefault(\"LINE_Y_AWAY_M\", p.get(\"LINE_Y_DEFAULT_M\", 50.0))\n    p.setdefault(\"MEDIAN_X_M\", 0.0)\n    xml = getattr(cfg, \"CALIB_XML\", None)\n    p[\"mode\"] = \"xml\" if xml else \"nilai\"\n    p[\"CALIB_XML\"] = xml\n    p[\"tersimpan\"] = None\n    return p\n\n\ndef profil(node_id):\n    _cek_node(node_id)\n    p = _profil_bawaan()\n    p.update(_baca_json(_jalur_profil(node_id), {}))\n    p[\"ada_xml\"] = bool(p.get(\"CALIB_XML\") and os.path.exists(p[\"CALIB_XML\"]))\n    return p\n\n\ndef _rapikan_profil(node_id, data, dasar):\n    \"\"\"Gabungkan nilai dari formulir ke profil `dasar`, dengan pemeriksaan batas.\"\"\"\n    p = dict(dasar)\n    for k in KUNCI_PROFIL:\n        if k in data and data[k] not in (\"\", None):\n            try:\n                v = float(data[k])\n            except (TypeError, ValueError):\n                raise Salah(\"Nilai %s bukan angka.\" % k)\n            lo, hi = BATAS_PROFIL[k]\n            if not lo <= v <= hi:\n                raise Salah(\"Nilai %s harus di antara %g dan %g.\" % (k, lo, hi))\n            p[k] = v\n    mode = data.get(\"mode\") or p.get(\"mode\", \"nilai\")\n    if mode not in (\"nilai\", \"xml\"):\n        raise Salah(\"Mode kalibrasi tidak dikenal.\")\n    p[\"mode\"] = mode\n    return p\n\n\ndef simpan_profil(node_id, data, xml=None):\n    \"\"\"data: nilai formulir; xml: isi berkas kalibrasi (bytes) bila diunggah.\"\"\"\n    _cek_node(node_id)\n    p = _rapikan_profil(node_id, data, profil(node_id))\n    if xml:\n        _cek_xml(xml)\n        jalur = os.path.join(DATA_APP, \"kamera\", node_id + \".xml\")\n        os.makedirs(os.path.dirname(jalur), exist_ok=True)\n        with open(jalur, \"wb\") as f:\n            f.write(xml)\n        p[\"CALIB_XML\"] = jalur\n    if p[\"mode\"] == \"xml\" and not (p.get(\"CALIB_XML\") and os.path.exists(p[\"CALIB_XML\"])):\n        raise Salah(\"Mode berkas kalibrasi dipilih, tetapi berkasnya belum diunggah.\")\n    p[\"tersimpan\"] = time.strftime(\"%Y-%m-%d %H:%M:%S\")\n    p.pop(\"ada_xml\", None)\n    _tulis_json(_jalur_profil(node_id), p)\n    return profil(node_id)\n\n\ndef _cek_xml(isi):\n    import xml.etree.ElementTree as ET\n    if len(isi) > 1024 * 1024:\n        raise Salah(\"Berkas kalibrasi terlalu besar.\")\n    try:\n        akar = ET.fromstring(isi)\n        float(akar.findtext(\"f\"))\n        float(akar.findtext(\"h\"))\n        if len(akar.findtext(\"vanishPoints\").split()) < 4:\n            raise ValueError\n    except Exception:\n        raise Salah(\"Berkas kalibrasi tidak dikenali. Yang didukung: XML dengan <f>, <h>, dan <vanishPoints> \"\n                    \"(format calibParams BrnoCompSpeed).\")\n\n\ndef _profil_pipeline(p):\n    \"\"\"Bentuk yang dibaca config.py pipeline lewat variabel lingkungan PROFIL_KAMERA.\"\"\"\n    out = {k: p[k] for k in KUNCI_PROFIL if k in p}\n    out[\"CALIB_XML\"] = p.get(\"CALIB_XML\") if p.get(\"mode\") == \"xml\" else None\n    return out\n\n\ndef _sumber_video(sumber):\n    \"\"\"sumber = 'contoh/<nama>' atau 'rekaman/<node>/<nama>' -> jalur berkas.\"\"\"\n    bagian = (sumber or \"\").split(\"/\")\n    if len(bagian) == 2 and bagian[0] == \"contoh\" and bagian[1] in daftar_contoh():\n        return os.path.join(VIDEO_DIR, bagian[1])\n    if len(bagian) == 3 and bagian[0] == \"rekaman\" and NODE_SAH.match(bagian[1]) and NAMA_REKAMAN.match(bagian[2]):\n        p = os.path.join(REKAMAN, bagian[1], bagian[2])\n        if os.path.exists(p):\n            return p\n    raise Salah(\"Video tidak ditemukan.\")\n\n\ndef pratinjau(node_id, data, sumber, posisi=0.5, xml=None):\n    \"\"\"Gambar PNG: frame video dengan kisi jalan, garis hitung, dan kotak mobil acuan untuk profil yang\n    sedang disunting (belum tentu tersimpan). Geometri dihitung oleh kode pipeline sendiri.\"\"\"\n    import cv2\n    _cek_node(node_id)\n    p = _rapikan_profil(node_id, data, profil(node_id))\n    video = _sumber_video(sumber)\n    with tempfile.TemporaryDirectory() as d:\n        if xml:\n            _cek_xml(xml)\n            p[\"CALIB_XML\"] = os.path.join(d, \"kalibrasi.xml\")\n            open(p[\"CALIB_XML\"], \"wb\").write(xml)\n        if p[\"mode\"] == \"xml\" and not (p.get(\"CALIB_XML\") and os.path.exists(p[\"CALIB_XML\"])):\n            raise Salah(\"Mode berkas kalibrasi dipilih, tetapi berkasnya belum diunggah.\")\n        cap = cv2.VideoCapture(video)\n        n = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))\n        cap.set(cv2.CAP_PROP_POS_FRAMES, max(0, min(n - 1, int(n * min(max(float(posisi), 0.0), 1.0)))))\n        ok, fr = cap.read()\n        cap.release()\n        if not ok:\n            raise Salah(\"Frame video tidak bisa dibaca.\")\n        fr = cv2.resize(fr, (cfg.IMG_W, cfg.IMG_H), interpolation=cv2.INTER_AREA)\n        cv2.imwrite(os.path.join(d, \"frame.jpg\"), fr)\n        _tulis_json(os.path.join(d, \"profil.json\"), _profil_pipeline(p))\n        r = subprocess.run(\n            [PYTHON, os.path.join(os.path.dirname(os.path.abspath(__file__)), \"pratinjau_kalibrasi.py\"),\n             os.path.join(d, \"frame.jpg\"), os.path.join(d, \"hasil.jpg\")],\n            cwd=PIPELINE, env=dict(os.environ, PROFIL_KAMERA=os.path.join(d, \"profil.json\")),\n            capture_output=True, timeout=60)\n        if r.returncode != 0:\n            raise Salah(\"Pratinjau gagal: \" + r.stderr.decode(errors=\"replace\")[-300:])\n        return open(os.path.join(d, \"hasil.jpg\"), \"rb\").read()\n\n\n# ====================================================================== 3. rekaman\ndef daftar_rekaman(node_id=None):\n    dipakai = {}\n    with _kunci:\n        for j in _jobs.values():\n            if j.get(\"sumber\", \"\").startswith(\"rekaman/\"):\n                dipakai.setdefault(j[\"sumber\"], []).append({\"id\": j[\"id\"], \"status\": j[\"status\"]})\n    out = []\n    for n in ([node_id] if node_id else [x[\"id\"] for x in setelan()[\"node\"]]):\n        d = os.path.join(REKAMAN, n)\n        if not NODE_SAH.match(n) or not os.path.isdir(d):\n            continue\n        for f in os.listdir(d):\n            m = NAMA_REKAMAN.match(f)\n            if not m:\n                continue\n            tgl, jam, mode = m.groups()\n            sumber = \"rekaman/%s/%s\" % (n, f)\n            out.append({\"sumber\": sumber, \"node\": n, \"nama\": f, \"mode\": mode,\n                        \"waktu\": \"%s-%s-%s %s:%s:%s\" % (tgl[:4], tgl[4:6], tgl[6:], jam[:2], jam[2:4], jam[4:]),\n                        \"ukuran_mb\": round(os.path.getsize(os.path.join(d, f)) / 1048576, 1),\n                        \"job\": dipakai.get(sumber, [])})\n    return sorted(out, key=lambda r: r[\"waktu\"], reverse=True)\n\n\ndef simpan_rekaman(node_id, berkas, mode, nama_asli=\"rekaman.mp4\"):\n    \"\"\"Simpan rekaman (dari node atau unggahan manual di peramban). Mengembalikan 'rekaman/<node>/<nama>'.\"\"\"\n    _cek_node(node_id)\n    if mode not in (\"otomatis\", \"manual\"):\n        raise Salah(\"Mode rekaman tidak dikenal.\")\n    if os.path.splitext(nama_asli or \"\")[1].lower() not in EKSTENSI:\n        raise Salah(\"Jenis berkas tidak didukung. Pakai: \" + \", \".join(EKSTENSI))\n    d = os.path.join(REKAMAN, node_id)\n    os.makedirs(d, exist_ok=True)\n    while True:\n        nama = time.strftime(\"%Y%m%d_%H%M%S_\") + mode + \".mp4\"\n        if not os.path.exists(os.path.join(d, nama)):\n            break\n        time.sleep(1)\n    sementara = os.path.join(d, nama + \".bagian\")\n    total = 0\n    try:\n        with open(sementara, \"wb\") as f:\n            while True:\n                potong = berkas.read(1024 * 1024)\n                if not potong:\n                    break\n                total += len(potong)\n                if total > MAKS_UNGGAH:\n                    raise Salah(\"Berkas terlalu besar (maksimum %d MB).\" % (MAKS_UNGGAH // 1048576))\n                f.write(potong)\n        if total == 0:\n            raise Salah(\"Berkas kosong.\")\n        tujuan = os.path.join(d, nama)\n        if os.path.splitext(nama_asli)[1].lower() == \".mp4\" or not shutil.which(\"ffmpeg\"):\n            os.replace(sementara, tujuan)\n        else:                                   # samakan wadah menjadi mp4\n            r = subprocess.run([\"ffmpeg\", \"-y\", \"-loglevel\", \"error\", \"-i\", sementara, \"-an\", \"-c:v\", \"libx264\",\n                                \"-preset\", \"veryfast\", \"-pix_fmt\", \"yuv420p\", tujuan])\n            if r.returncode != 0:\n                raise Salah(\"Video tidak bisa dibaca.\")\n    finally:\n        if os.path.exists(sementara):\n            os.remove(sementara)\n    return \"rekaman/%s/%s\" % (node_id, nama)\n\n\ndef hapus_rekaman(sumber):\n    p = _sumber_video(sumber)\n    if not sumber.startswith(\"rekaman/\"):\n        raise Salah(\"Hanya rekaman yang bisa dihapus.\")\n    with _kunci:\n        if any(j.get(\"sumber\") == sumber and j[\"status\"] in (\"antre\", \"proses\") for j in _jobs.values()):\n            raise Salah(\"Rekaman ini sedang diproses.\")\n    os.remove(p)\n    for f in os.listdir(os.path.dirname(p)):               # cache deteksi milik rekaman itu\n        if f.startswith(os.path.basename(p) + \".\") and f.endswith(\".det.pkl\"):\n            os.remove(os.path.join(os.path.dirname(p), f))\n\n\n# ====================================================================== 4. node (Raspberry Pi)\ndef token_sah(token):\n    return bool(token) and hmac.compare_digest(str(token), str(setelan()[\"token_node\"]))\n\n\ndef minta_rekam(node_id, durasi):\n    \"\"\"Dari halaman web: minta node merekam sekarang. Node mengambil permintaan ini saat menanyakan tugas.\"\"\"\n    _cek_node(node_id)\n    try:\n        durasi = int(float(durasi))\n    except (TypeError, ValueError):\n        raise Salah(\"Durasi bukan angka.\")\n    if not 5 <= durasi <= 1800:\n        raise Salah(\"Durasi harus 5 sampai 1800 detik.\")\n    r = {\"id\": secrets.token_hex(4), \"node\": node_id, \"durasi_detik\": durasi, \"status\": \"menunggu node\",\n         \"dibuat\": time.strftime(\"%Y-%m-%d %H:%M:%S\"), \"t\": time.time()}\n    with _kunci:\n        _permintaan.append(r)\n        del _permintaan[:-50]\n    return r\n\n\ndef daftar_permintaan(node_id=None):\n    with _kunci:\n        for r in _permintaan:                       # node tidak pernah mengambil / tidak pernah mengirim\n            if r[\"status\"] in (\"menunggu node\", \"merekam\") and time.time() - r[\"t\"] > r[\"durasi_detik\"] + 600:\n                r[\"status\"] = \"gagal (node tidak menjawab)\"\n        return [dict(r) for r in reversed(_permintaan) if node_id in (None, r[\"node\"])]\n\n\ndef _slot_terisi(node_id, tanggal):\n    \"\"\"Jam jadwal hari ini yang rekamannya sudah diterima (agar tidak direkam dua kali).\"\"\"\n    return _baca_json(os.path.join(REKAMAN, node_id, \"slot_%s.json\" % tanggal), [])\n\n\ndef node_tugas(node_id):\n    \"\"\"Dipanggil node tiap beberapa detik. Mengembalikan jadwal hari ini dan permintaan manual yang menunggu.\"\"\"\n    _cek_node(node_id)\n    _terlihat[node_id] = time.time()\n    manual = []\n    with _kunci:\n        for r in _permintaan:\n            if r[\"node\"] == node_id and r[\"status\"] == \"menunggu node\":\n                r[\"status\"] = \"merekam\"\n                manual.append({\"id\": r[\"id\"], \"durasi_detik\": r[\"durasi_detik\"]})\n    tanggal = time.strftime(\"%Y%m%d\")\n    return {\"waktu_server\": time.strftime(\"%Y-%m-%d %H:%M:%S\"), \"tanggal\": tanggal,\n            \"durasi_detik\": int(setelan()[\"jadwal\"][\"durasi_detik\"]), \"jadwal\": jadwal_harian(),\n            \"sudah\": _slot_terisi(node_id, tanggal), \"manual\": manual}\n\n\ndef node_unggah(node_id, berkas, mode, slot=\"\", id_permintaan=\"\", nama_asli=\"rekaman.mp4\"):\n    \"\"\"Node mengirim hasil rekaman. Otomatis -> langsung diproses. Manual -> disimpan saja.\"\"\"\n    _cek_node(node_id)\n    _terlihat[node_id] = time.time()\n    tanggal = time.strftime(\"%Y%m%d\")\n    if mode == \"otomatis\":\n        if slot not in jadwal_harian():\n            raise Salah(\"Jam jadwal tidak dikenal: %s\" % slot)\n        if slot in _slot_terisi(node_id, tanggal):\n            raise Salah(\"Rekaman untuk jadwal %s sudah diterima.\" % slot)\n    sumber = simpan_rekaman(node_id, berkas, mode, nama_asli)\n    hasil = {\"sumber\": sumber}\n    if mode == \"otomatis\":\n        _tulis_json(os.path.join(REKAMAN, node_id, \"slot_%s.json\" % tanggal), _slot_terisi(node_id, tanggal) + [slot])\n        try:\n            hasil[\"job\"] = buat_job(sumber=sumber, node_id=node_id)[\"id\"]\n        except Exception as e:                    # rekaman tetap tersimpan walau gagal masuk antrean\n            hasil[\"galat\"] = str(e)\n    else:\n        with _kunci:\n            for r in _permintaan:\n                if r[\"id\"] == id_permintaan:\n                    r[\"status\"] = \"selesai\"\n                    r[\"sumber\"] = sumber\n    return hasil\n\n\n# ====================================================================== 5. pekerjaan (job)\ndef _folder(job_id):\n    return os.path.join(DATA, job_id)\n\n\ndef _simpan(st):\n    _tulis_json(os.path.join(_folder(st[\"id\"]), \"status.json\"), st)\n\n\ndef _ubah(job_id, **kw):\n    with _kunci:\n        st = _jobs[job_id]\n        st.update(kw)\n        _simpan(st)\n\n\ndef muat_dari_disk():\n    \"\"\"Saat server mulai: baca job lama; job yang terputus ditandai gagal.\"\"\"\n    os.makedirs(DATA, exist_ok=True)\n    setelan()\n    with _kunci:\n        for n in sorted(os.listdir(DATA)):\n            st = _baca_json(os.path.join(DATA, n, \"status.json\"))\n            if not ID_SAH.match(n) or not st:\n                continue\n            _jobs[n] = st\n            if st.get(\"status\") in (\"antre\", \"proses\"):\n                st.update(status=\"gagal\", tahap=\"Gagal\", pesan=\"Server dimulai ulang saat video ini sedang diproses.\")\n                _simpan(st)\n\n\ndef _ringkas_status(st):\n    return {k: st.get(k) for k in (\"id\", \"nama_video\", \"sumber\", \"node\", \"model\", \"dibuat\", \"waktu_video\", \"status\",\n                                   \"tahap\", \"progres\", \"total\", \"per_kelas\", \"pemicu\")}\n\n\ndef daftar_job():\n    with _kunci:\n        return sorted((_ringkas_status(s) for s in _jobs.values()), key=lambda s: s[\"id\"], reverse=True)\n\n\ndef ambil_job(job_id):\n    with _kunci:\n        st = _jobs.get(job_id)\n        if st is None:\n            return None\n        st = dict(st)\n    if st[\"status\"] == \"selesai\":\n        st[\"ringkasan\"] = _baca_json(os.path.join(_folder(job_id), \"ringkasan.json\"))\n    return st\n\n\ndef jalur_berkas(job_id, nama):\n    if not ID_SAH.match(job_id) or nama not in (\"hasil.mp4\", \"counting_log.csv\", \"keluaran.txt\"):\n        return None\n    p = os.path.join(_folder(job_id), nama)\n    return p if os.path.exists(p) else None\n\n\ndef hapus_job(job_id):\n    with _kunci:\n        st = _jobs.get(job_id)\n        if st is None:\n            return \"tidak ada\"\n        if st[\"status\"] in (\"antre\", \"proses\"):\n            return \"sedang berjalan\"\n        del _jobs[job_id]\n    shutil.rmtree(_folder(job_id), ignore_errors=True)\n    return \"ok\"\n\n\ndef _angka(nilai, bawaan, lo, hi):\n    try:\n        v = float(nilai)\n    except (TypeError, ValueError):\n        return bawaan\n    return min(max(v, lo), hi)\n\n\ndef buat_job(sumber, node_id, model=None, conf=None, conf_low=None, pemicu=None):\n    \"\"\"sumber: 'contoh/<nama>' atau 'rekaman/<node>/<nama>'. Profil kamera diambil dari node_id.\"\"\"\n    _cek_node(node_id)\n    video = _sumber_video(sumber)\n    model = model or (daftar_model() or [None])[0]\n    if model not in daftar_model():\n        raise Salah(\"Bobot model tidak ditemukan: %s\" % model)\n    b = info()[\"bawaan\"]\n    s = {\"conf\": _angka(conf, b[\"conf\"], 0.05, 0.95), \"conf_low\": _angka(conf_low, b[\"conf_low\"], 0.0, 0.9)}\n    if s[\"conf_low\"] >= s[\"conf\"]:\n        raise Salah(\"Ambang rendah harus lebih kecil dari ambang deteksi (atau 0 untuk mematikan).\")\n    p = profil(node_id)\n    if p[\"mode\"] == \"xml\" and not p[\"ada_xml\"]:\n        raise Salah(\"Profil kamera %s memakai berkas kalibrasi yang tidak ada. Buka halaman Kalibrasi.\" % node_id)\n\n    m = NAMA_REKAMAN.match(os.path.basename(video))\n    if m:\n        t, j = m.group(1), m.group(2)\n        waktu_video = \"%s-%s-%s %s:%s:%s\" % (t[:4], t[4:6], t[6:], j[:2], j[2:4], j[4:])\n        pemicu = pemicu or m.group(3)\n    else:\n        waktu_video = time.strftime(\"%Y-%m-%d %H:%M:%S\", time.localtime(os.path.getmtime(video)))\n        pemicu = pemicu or \"contoh\"\n    job_id = time.strftime(\"%Y%m%d-%H%M%S-\") + secrets.token_hex(2)\n    os.makedirs(_folder(job_id))\n    _tulis_json(os.path.join(_folder(job_id), \"profil.json\"), _profil_pipeline(p))\n    st = {\"id\": job_id, \"nama_video\": os.path.basename(video), \"sumber\": sumber, \"node\": node_id, \"model\": model,\n          \"dibuat\": time.strftime(\"%Y-%m-%d %H:%M:%S\"), \"waktu_video\": waktu_video, \"pemicu\": pemicu,\n          \"status\": \"antre\", \"tahap\": \"Menunggu giliran\", \"progres\": 0.0, \"setelan\": s,\n          \"garis\": {\"mendekat\": p[\"LINE_Y_DEFAULT_M\"], \"menjauh\": p[\"LINE_Y_AWAY_M\"], \"median\": p[\"MEDIAN_X_M\"]},\n          \"masukan\": video, \"cache\": _jalur_cache(video, model), \"pesan\": \"\"}\n    with _kunci:\n        _jobs[job_id] = st\n        _simpan(st)\n    _mulai_pekerja()\n    _antrean.put(job_id)\n    return dict(st)\n\n\ndef _jalur_cache(video, model):\n    \"\"\"Cache deteksi bergantung pada video DAN model, jadi nama model ikut di nama berkas.\"\"\"\n    khusus = CACHE_KHUSUS.get((os.path.basename(video), model))\n    if khusus and os.path.exists(os.path.join(os.path.dirname(video), khusus)):\n        return os.path.join(os.path.dirname(video), khusus)\n    return \"%s.%s.det.pkl\" % (video, os.path.splitext(model)[0])\n\n\ndef _mulai_pekerja():\n    global _pekerja\n    with _kunci:\n        if _pekerja is None or not _pekerja.is_alive():\n            _pekerja = threading.Thread(target=_putaran, daemon=True)\n            _pekerja.start()\n\n\ndef _putaran():\n    while True:\n        job_id = _antrean.get()\n        try:\n            _kerjakan(job_id)\n        except Exception as e:\n            try:\n                _ubah(job_id, status=\"gagal\", tahap=\"Gagal\", pesan=\"Galat internal: %s\" % e)\n            except Exception:\n                pass\n\n\ndef _siapkan_video(job_id, jalur):\n    \"\"\"Pastikan video berukuran IMG_W x IMG_H; bila tidak, buat salinan yang diubah ukurannya.\"\"\"\n    import cv2\n    cap = cv2.VideoCapture(jalur)\n    if not cap.isOpened():\n        raise RuntimeError(\"Video tidak bisa dibuka.\")\n    w, h = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH)), int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))\n    n, fps = int(cap.get(cv2.CAP_PROP_FRAME_COUNT)), cap.get(cv2.CAP_PROP_FPS)\n    fps = fps if fps and fps > 1 else 25.0\n    if (w, h) == (cfg.IMG_W, cfg.IMG_H):\n        cap.release()\n        return jalur, n, fps\n    _ubah(job_id, tahap=\"Mengubah ukuran video ke %dx%d\" % (cfg.IMG_W, cfg.IMG_H))\n    baru = os.path.join(_folder(job_id), \"masukan_%dp.mp4\" % cfg.IMG_H)\n    out = cv2.VideoWriter(baru, cv2.VideoWriter_fourcc(*\"mp4v\"), fps, (cfg.IMG_W, cfg.IMG_H))\n    i = 0\n    while True:\n        ok, fr = cap.read()\n        if not ok:\n            break\n        out.write(cv2.resize(fr, (cfg.IMG_W, cfg.IMG_H), interpolation=cv2.INTER_AREA))\n        i += 1\n        if i % 25 == 0 and n:\n            _ubah(job_id, progres=round(0.1 * i / n, 3))\n    cap.release()\n    out.release()\n    return baru, i, fps\n\n\ndef _kerjakan(job_id):\n    st = ambil_job(job_id)\n    if st is None:\n        return\n    folder, s = _folder(job_id), st[\"setelan\"]\n    _ubah(job_id, status=\"proses\", tahap=\"Menyiapkan video\", mulai=time.time())\n    if not os.path.exists(st[\"masukan\"]):\n        _ubah(job_id, status=\"gagal\", tahap=\"Gagal\", pesan=\"Berkas video sudah tidak ada.\")\n        return\n    try:\n        video, n_frame, fps = _siapkan_video(job_id, st[\"masukan\"])\n    except Exception as e:\n        _ubah(job_id, status=\"gagal\", tahap=\"Gagal\", pesan=str(e))\n        return\n    pakai_cache = os.path.exists(st[\"cache\"])\n    _ubah(job_id, frame_total=n_frame, fps=fps,\n          tahap=\"Melacak dan menghitung (deteksi dari cache)\" if pakai_cache else \"Mendeteksi kendaraan (tanpa GPU, lambat)\")\n\n    cmd = [PYTHON, \"run.py\", video, os.path.join(MODEL_DIR, st[\"model\"]), \"--no-show\",\n           \"--out\", os.path.join(folder, \"hasil.mp4\"), \"--cache\", st[\"cache\"], \"--conf\", str(s[\"conf\"])]\n    if s[\"conf_low\"] > 0:\n        cmd += [\"--conf-low\", str(s[\"conf_low\"])]\n    cmd += os.environ.get(\"ANTARMUKA_ARG_TAMBAHAN\", \"\").split()   # mis. --tanpa-gambar\n    env = dict(os.environ, PROFIL_KAMERA=os.path.join(folder, \"profil.json\"))\n    log = open(os.path.join(folder, \"keluaran.txt\"), \"wb\")\n    p = subprocess.Popen(cmd, cwd=PIPELINE, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)\n    baris, terakhir = b\"\", 0.0\n    while True:\n        c = p.stdout.read(1)\n        if not c:\n            break\n        if c in (b\"\\r\", b\"\\n\"):\n            m = POLA_PROGRES.search(baris)\n            if m and int(m.group(2)) > 0:\n                if time.time() - terakhir > 0.5:\n                    terakhir = time.time()\n                    _ubah(job_id, progres=round(0.1 + 0.85 * int(m.group(1)) / int(m.group(2)), 3))\n            elif baris.strip():\n                log.write(baris + b\"\\n\")\n                log.flush()\n            baris = b\"\"\n        else:\n            baris += c\n    kode = p.wait()\n    log.close()\n    if kode != 0:\n        ekor = open(os.path.join(folder, \"keluaran.txt\"), errors=\"replace\").read()[-600:]\n        _ubah(job_id, status=\"gagal\", tahap=\"Gagal\", pesan=\"Pipeline berhenti dengan galat:\\n\" + ekor)\n        return\n    try:\n        shutil.copy(os.path.join(PIPELINE, cfg.COUNT_LOG), os.path.join(folder, \"counting_log.csv\"))\n        r = ringkas(os.path.join(folder, \"counting_log.csv\"), fps, n_frame, st[\"garis\"][\"median\"])\n        _tulis_json(os.path.join(folder, \"ringkasan.json\"), r)\n    except Exception as e:\n        _ubah(job_id, status=\"gagal\", tahap=\"Gagal\", pesan=\"Hasil tidak bisa dibaca: %s\" % e)\n        return\n    st2 = ambil_job(job_id)\n    _ubah(job_id, status=\"selesai\", tahap=\"Selesai\", progres=1.0, total=r[\"total\"], per_kelas=r[\"per_kelas\"],\n          lama_detik=round(time.time() - st2.get(\"mulai\", time.time()), 1),\n          ada_video=os.path.exists(os.path.join(folder, \"hasil.mp4\")))\n\n\n# ====================================================================== 6. ringkasan hasil\ndef ringkas(csv_path, fps, n_frame, median=None):\n    \"\"\"Ringkas counting_log.csv: per kelas, per arah, per rentang waktu, dan daftar kendaraan.\"\"\"\n    kelas = list(cfg.CLASSES)\n    durasi = n_frame / fps if fps else 0.0\n    langkah = next((x for x in (5, 10, 15, 30, 60, 120, 300, 600, 1800, 3600) if durasi / x <= 12), 3600)\n    n_bak = max(1, int(durasi // langkah) + (1 if durasi % langkah else 0))\n    waktu = [dict({\"mulai\": i * langkah}, **{c: 0 for c in kelas}) for i in range(n_bak)]\n    per_kelas = {c: 0 for c in kelas}\n    per_arah = {\"mendekat\": 0, \"menjauh\": 0}\n    kendaraan = []\n    with open(csv_path, newline=\"\", encoding=\"utf-8\") as f:\n        for r in csv.DictReader(f):\n            k = r[\"kelas\"]\n            if k not in per_kelas:\n                continue\n            fr, x = int(r[\"frame\"]), float(r[\"x_m\"])\n            t = fr / fps if fps else 0.0\n            arah = \"menjauh\" if (median is not None and x >= median) else \"mendekat\"\n            per_kelas[k] += 1\n            per_arah[arah] += 1\n            waktu[min(int(t // langkah), n_bak - 1)][k] += 1\n            skor = r.get(\"suara_\" + k, \"\")\n            kendaraan.append({\"frame\": fr, \"detik\": round(t, 2), \"id\": int(r[\"id\"]), \"kelas\": k, \"arah\": arah,\n                              \"panjang_m\": float(r[\"panjang_m\"]), \"x_m\": x,\n                              \"skor\": float(skor) if skor not in (\"\", None) else None})\n    return {\"total\": len(kendaraan), \"per_kelas\": per_kelas, \"per_arah\": per_arah, \"ada_arah\": median is not None,\n            \"durasi_detik\": round(durasi, 1), \"langkah_detik\": langkah, \"per_waktu\": waktu, \"kendaraan\": kendaraan}\n", "backend/pratinjau_kalibrasi.py": "\"\"\"\npratinjau_kalibrasi.py - menggambar kisi jalan, garis hitung, dan kotak mobil acuan di atas satu frame.\n\nDijalankan layanan.py DARI folder pipeline, dengan variabel lingkungan PROFIL_KAMERA berisi profil\nyang sedang disunting, sehingga geometri yang dipakai persis sama dengan yang dipakai run.py.\n    python pratinjau_kalibrasi.py frame.jpg hasil.jpg\nKalibrasi benar bila: garis kisi sejajar marka jalan, dan kotak acuan (4,5 x 1,8 x 1,5 m)\nseukuran mobil yang berada di dekatnya.\n\"\"\"\nimport os\nimport sys\n\nsys.path.insert(0, os.getcwd())\n\nimport cv2                      # noqa: E402\nimport numpy as np              # noqa: E402\n\nimport config as cfg            # noqa: E402\nfrom box3d import box_corners   # noqa: E402\nfrom geometry import CAMERA_POS, TO_CAMERA_FROM_WORLD, world_to_image  # noqa: E402\n\nframe = cv2.imread(sys.argv[1])\nH, W = frame.shape[:2]\n\n\ndef piksel(x, z, y=0.0):\n    \"\"\"Titik dunia -> piksel, atau None bila di belakang kamera / terlalu jauh dari gambar.\"\"\"\n    p = np.array([x, y, z], dtype=float)\n    if (TO_CAMERA_FROM_WORLD[:3, :3] @ p + TO_CAMERA_FROM_WORLD[:3, 3])[2] <= 0.5:\n        return None\n    u, v = world_to_image(p, H)\n    return (u, v) if abs(u) < 20000 and abs(v) < 20000 else None\n\n\ndef garis(a, b, warna, tebal=1):\n    if a is None or b is None:\n        return\n    ok, p, q = cv2.clipLine((0, 0, W, H), a, b)\n    if ok:\n        cv2.line(frame, p, q, warna, tebal, cv2.LINE_AA)\n\n\nhalf, jauh = cfg.LANE_HALF_WIDTH_M, cfg.MAX_TRACK_DEPTH_M\nmedian = getattr(cfg, \"MEDIAN_X_M\", 0.0)\naway = getattr(cfg, \"LINE_Y_AWAY_M\", cfg.LINE_Y_DEFAULT_M)\nlangkah = 10 if jauh <= 150 else 20\nz0 = 5.0\n\n# kisi: garis melintang tiap `langkah` meter, garis memanjang tiap 5 m\nfor z in np.arange(langkah, jauh + 0.1, langkah):\n    garis(piksel(-half, z), piksel(half, z), (255, 255, 255), 1)\n    p = piksel(-half, z)\n    if p and 0 <= p[1] < H:\n        cv2.putText(frame, \"%d m\" % z, (max(4, min(W - 60, p[0] + 4)), p[1] - 4), cv2.FONT_HERSHEY_SIMPLEX, 0.45,\n                    (255, 255, 255), 1, cv2.LINE_AA)\nfor x in np.arange(-half, half + 0.1, 5.0):\n    garis(piksel(x, z0), piksel(x, jauh), (200, 200, 200), 1)\n# batas jalur (jingga) dan median (sian)\nfor x in (-half, half):\n    garis(piksel(x, z0), piksel(x, jauh), (0, 165, 255), 2)\ngaris(piksel(median, z0), piksel(median, jauh), (255, 255, 0), 2)\n# garis hitung: mendekat (merah, kiri median), menjauh (ungu, kanan median)\ngaris(piksel(-half, cfg.LINE_Y_DEFAULT_M), piksel(median, cfg.LINE_Y_DEFAULT_M), (0, 0, 255), 3)\ngaris(piksel(median, away), piksel(half, away), (255, 0, 255), 3)\n# kotak mobil acuan di beberapa jarak\ntepi = [(0, 1), (1, 2), (2, 3), (3, 0), (4, 5), (5, 6), (6, 7), (7, 4), (0, 4), (1, 5), (2, 6), (3, 7)]\nfor z in (jauh * 0.2, jauh * 0.4, jauh * 0.65):\n    for x in ((-half + median) / 2, (median + half) / 2):\n        pts = [piksel(c[0], c[2], c[1]) for c in box_corners(x, z, (1.8, 1.5, 4.5), 0.0)]\n        for a, b in tepi:\n            garis(pts[a], pts[b], (0, 255, 0), 2)\n\nteks = \"tinggi kamera %.2f m\" % CAMERA_POS[1]\ncv2.rectangle(frame, (8, 8), (16 + 9 * len(teks), 32), (0, 0, 0), -1)\ncv2.putText(frame, teks, (12, 26), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255, 255, 255), 1, cv2.LINE_AA)\ncv2.imwrite(sys.argv[2], frame, [cv2.IMWRITE_JPEG_QUALITY, 85])\n", "backend/jalankan.sh": "#!/bin/bash\n# Menjalankan server antarmuka. Buka http://127.0.0.1:8000 di peramban. Berhenti: Ctrl+C.\n# Bila \"izinkan_jaringan\" di ../data/setelan.json bernilai true, server juga menerima kiriman\n# Raspberry Pi dari jaringan (hanya alamat /api/node/... dan wajib token).\ncd \"$(dirname \"$0\")\" || exit 1\nsource ~/projects/venv_3dbbox/bin/activate\nHOST=127.0.0.1\nif python3 -c \"import json,sys; sys.exit(0 if json.load(open('../data/setelan.json')).get('izinkan_jaringan') else 1)\" 2>/dev/null; then\n  HOST=0.0.0.0\nfi\necho \"Server di http://127.0.0.1:8000 (menerima dari: $HOST)\"\nexec uvicorn app:app --host \"$HOST\" --port 8000\n", "frontend/index.html": "<!doctype html>\n<html lang=\"id\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Penghitung Kendaraan 3D</title>\n<link rel=\"stylesheet\" href=\"gaya.css\">\n</head>\n<body>\n<header class=\"atas\">\n  <div>\n    <h1>Penghitung Kendaraan 3D</h1>\n    <p class=\"sub\">Deteksi kotak 3D, pelacakan, klasifikasi 4 kelas, dan penghitungan</p>\n  </div>\n</header>\n<nav class=\"nav\" aria-label=\"Halaman\">\n  <a href=\"#/rekam\" data-hal=\"rekam\">Pengambilan video</a>\n  <a href=\"#/kalibrasi\" data-hal=\"kalibrasi\">Kalibrasi kamera</a>\n  <a href=\"#/proses\" data-hal=\"proses\">Proses</a>\n  <a href=\"#/hasil\" data-hal=\"hasil\">Hasil</a>\n</nav>\n<div id=\"masalah\" class=\"peringatan\" hidden></div>\n\n<!-- ================= Pengambilan video ================= -->\n<main id=\"hal_rekam\" class=\"halaman\" hidden>\n  <div class=\"dua\">\n    <div class=\"kolom\">\n      <section class=\"kartu\">\n        <h2>Kamera (node)</h2>\n        <label for=\"rekam_node\">Node</label>\n        <select id=\"rekam_node\"></select>\n        <p class=\"status\" style=\"margin-top:10px\"><span id=\"node_lampu\" class=\"lampu\"></span><span id=\"node_status\"></span></p>\n      </section>\n      <section class=\"kartu\">\n        <h2>Pengambilan otomatis</h2>\n        <dl class=\"rinci\">\n          <dt>Video per hari</dt><dd id=\"jadwal_n\"></dd>\n          <dt>Durasi tiap video</dt><dd id=\"jadwal_durasi\"></dd>\n          <dt>Rentang jam</dt><dd id=\"jadwal_rentang\"></dd>\n        </dl>\n        <ul id=\"jadwal_jam\" class=\"jam\"></ul>\n        <p class=\"redup\">Jadwal ini tetap dan tidak bisa diubah dari halaman. Rekaman otomatis langsung diproses. Berkas setelan: <code id=\"jadwal_berkas\"></code></p>\n      </section>\n      <section class=\"kartu\">\n        <h2>Pengambilan manual</h2>\n        <form id=\"form_rekam\" class=\"baris\">\n          <div><label for=\"rekam_durasi\">Durasi (detik)</label><input id=\"rekam_durasi\" type=\"number\" min=\"5\" max=\"1800\" step=\"5\" value=\"30\"></div>\n          <button class=\"utamakan\" type=\"submit\">Rekam sekarang</button>\n        </form>\n        <p id=\"rekam_pesan\" class=\"galat\" hidden></p>\n        <ul id=\"permintaan\" class=\"riwayat\" style=\"margin-top:10px\"></ul>\n        <form id=\"form_unggah\" style=\"margin-top:14px\">\n          <label for=\"unggah_berkas\">atau unggah berkas video</label>\n          <input id=\"unggah_berkas\" type=\"file\" accept=\".mp4,.avi,.mov,.mkv,video/*\">\n          <button class=\"polos\" type=\"submit\" style=\"margin-top:8px\">Unggah</button>\n        </form>\n        <p id=\"unggah_pesan\" class=\"galat\" hidden></p>\n        <p class=\"redup\">Rekaman manual hanya disimpan. Pilih di tabel untuk memprosesnya.</p>\n      </section>\n    </div>\n    <section class=\"kartu\">\n      <h2>Rekaman tersimpan</h2>\n      <div class=\"gulir\">\n        <table>\n          <thead><tr><th>Waktu rekam</th><th>Jenis</th><th class=\"kanan\">Ukuran</th><th>Status</th><th></th></tr></thead>\n          <tbody id=\"tabel_rekaman\"></tbody>\n        </table>\n      </div>\n      <p id=\"rekaman_kosong\" class=\"redup\" hidden>Belum ada rekaman dari node ini.</p>\n    </section>\n  </div>\n</main>\n\n<!-- ================= Kalibrasi kamera ================= -->\n<main id=\"hal_kalibrasi\" class=\"halaman\" hidden>\n  <div class=\"dua\">\n    <form id=\"form_kal\" class=\"kolom\">\n      <section class=\"kartu\">\n        <h2>Profil kamera</h2>\n        <label for=\"kal_node\">Node</label>\n        <select id=\"kal_node\"></select>\n        <p id=\"kal_tersimpan\" class=\"redup\"></p>\n        <label for=\"kal_sumber\">Video untuk pratinjau</label>\n        <select id=\"kal_sumber\"></select>\n        <label for=\"kal_posisi\">Posisi frame</label>\n        <input id=\"kal_posisi\" type=\"range\" min=\"0\" max=\"1\" step=\"0.01\" value=\"0.3\">\n      </section>\n      <section class=\"kartu\">\n        <h2>Kalibrasi</h2>\n        <div class=\"pilihan\" role=\"radiogroup\" aria-label=\"Cara kalibrasi\">\n          <label><input type=\"radio\" name=\"mode\" value=\"nilai\"> Atur nilai</label>\n          <label><input type=\"radio\" name=\"mode\" value=\"xml\"> Berkas kalibrasi</label>\n        </div>\n        <div id=\"kal_nilai\">\n          <label for=\"PITCH_DEG\">Sudut tunduk kamera (derajat)</label>\n          <div class=\"geser\"><input type=\"range\" data-untuk=\"PITCH_DEG\" min=\"0\" max=\"60\" step=\"0.1\"><input id=\"PITCH_DEG\" name=\"PITCH_DEG\" type=\"number\" step=\"0.1\"></div>\n          <label for=\"CAM_HEIGHT_M\">Tinggi kamera (m)</label>\n          <div class=\"geser\"><input type=\"range\" data-untuk=\"CAM_HEIGHT_M\" min=\"2\" max=\"30\" step=\"0.05\"><input id=\"CAM_HEIGHT_M\" name=\"CAM_HEIGHT_M\" type=\"number\" step=\"0.05\"></div>\n          <label for=\"FOCAL_PX\">Focal length (piksel)</label>\n          <div class=\"geser\"><input type=\"range\" data-untuk=\"FOCAL_PX\" min=\"300\" max=\"6000\" step=\"5\"><input id=\"FOCAL_PX\" name=\"FOCAL_PX\" type=\"number\" step=\"5\"></div>\n        </div>\n        <div id=\"kal_xml\" hidden>\n          <label for=\"xml\">Berkas kalibrasi (XML: f, h, vanishPoints)</label>\n          <input id=\"xml\" name=\"xml\" type=\"file\" accept=\".xml,text/xml\">\n          <p id=\"kal_xml_ket\" class=\"redup\"></p>\n        </div>\n      </section>\n      <section class=\"kartu\">\n        <h2>Jalur dan garis hitung</h2>\n        <div class=\"kisi2\">\n          <div><label for=\"LINE_Y_DEFAULT_M\">Garis mendekat (m)</label><input id=\"LINE_Y_DEFAULT_M\" name=\"LINE_Y_DEFAULT_M\" type=\"number\" step=\"1\"></div>\n          <div><label for=\"LINE_Y_AWAY_M\">Garis menjauh (m)</label><input id=\"LINE_Y_AWAY_M\" name=\"LINE_Y_AWAY_M\" type=\"number\" step=\"1\"></div>\n          <div><label for=\"MEDIAN_X_M\">Median, batas dua arah (m)</label><input id=\"MEDIAN_X_M\" name=\"MEDIAN_X_M\" type=\"number\" step=\"0.5\"></div>\n          <div><label for=\"LANE_HALF_WIDTH_M\">Setengah lebar jalur (m)</label><input id=\"LANE_HALF_WIDTH_M\" name=\"LANE_HALF_WIDTH_M\" type=\"number\" step=\"0.5\"></div>\n          <div><label for=\"MAX_TRACK_DEPTH_M\">Jarak terjauh (m)</label><input id=\"MAX_TRACK_DEPTH_M\" name=\"MAX_TRACK_DEPTH_M\" type=\"number\" step=\"5\"></div>\n        </div>\n        <button id=\"kal_simpan\" class=\"utamakan\" type=\"submit\" style=\"margin-top:14px;width:100%\">Simpan profil</button>\n        <p id=\"kal_pesan\" class=\"galat\" hidden></p>\n        <p id=\"kal_ok\" class=\"berhasil\" hidden></p>\n      </section>\n    </form>\n    <section class=\"kartu\">\n      <h2>Pratinjau</h2>\n      <img id=\"pratinjau_gbr\" alt=\"Frame video dengan kisi jalan, garis hitung, dan kotak mobil acuan\">\n      <p id=\"pratinjau_pesan\" class=\"galat\" hidden></p>\n      <p class=\"redup\">Kalibrasi sudah tepat bila garis kisi sejajar marka jalan dan kotak hijau (4,5 \u00d7 1,8 \u00d7 1,5 m) seukuran mobil di dekatnya.\n        Jingga: batas jalur. Sian: median. Merah: garis hitung mendekat. Ungu: garis hitung menjauh.</p>\n    </section>\n  </div>\n</main>\n\n<!-- ================= Proses ================= -->\n<main id=\"hal_proses\" class=\"halaman\" hidden>\n  <div class=\"dua\">\n    <section class=\"kartu\">\n      <h2>Proses video</h2>\n      <form id=\"form_proses\">\n        <label for=\"proses_sumber\">Video</label>\n        <select id=\"proses_sumber\"></select>\n        <label for=\"proses_node\">Profil kamera (node)</label>\n        <select id=\"proses_node\"></select>\n        <label for=\"proses_model\">Model (bobot .pth)</label>\n        <select id=\"proses_model\"></select>\n        <details>\n          <summary>Setelan deteksi</summary>\n          <div class=\"kisi2\">\n            <div><label for=\"conf\">Ambang deteksi</label><input id=\"conf\" type=\"number\" step=\"0.05\" min=\"0.05\" max=\"0.95\"></div>\n            <div><label for=\"conf_low\">Ambang rendah</label><input id=\"conf_low\" type=\"number\" step=\"0.05\" min=\"0\" max=\"0.9\"></div>\n          </div>\n        </details>\n        <button id=\"tombol\" type=\"submit\">Proses</button>\n        <p id=\"galat_form\" class=\"galat\" hidden></p>\n      </form>\n    </section>\n    <section class=\"kartu\">\n      <h2>Antrean</h2>\n      <div class=\"gulir\">\n        <table>\n          <thead><tr><th>Video</th><th>Model</th><th>Status</th><th class=\"kanan\">Progres</th></tr></thead>\n          <tbody id=\"tabel_antrean\"></tbody>\n        </table>\n      </div>\n      <p id=\"antrean_kosong\" class=\"redup\">Tidak ada video yang sedang diproses.</p>\n      <p class=\"redup\">Video diproses satu per satu. Video baru tanpa cache deteksi berjalan sekitar 2\u20133 frame per detik.</p>\n    </section>\n  </div>\n</main>\n\n<!-- ================= Hasil ================= -->\n<main id=\"hal_hasil\" class=\"halaman\" hidden>\n  <section id=\"hasil_daftar\" class=\"kartu\">\n    <h2>Hasil</h2>\n    <div class=\"baris\">\n      <div><label for=\"cari_nama\">Nama video</label><input id=\"cari_nama\" type=\"search\" placeholder=\"cari\u2026\"></div>\n      <div><label for=\"cari_tanggal\">Tanggal rekam</label><input id=\"cari_tanggal\" type=\"date\"></div>\n      <div><label for=\"cari_node\">Node</label><select id=\"cari_node\"></select></div>\n    </div>\n    <div class=\"gulir\" style=\"margin-top:12px\">\n      <table>\n        <thead><tr><th>Waktu rekam</th><th>Nama video</th><th>Node</th><th>Model</th><th>Jenis</th><th>Status</th><th class=\"kanan\">Total</th><th id=\"kepala_kelas\"></th></tr></thead>\n        <tbody id=\"tabel_hasil\"></tbody>\n      </table>\n    </div>\n    <p id=\"hasil_kosong\" class=\"redup\" hidden>Tidak ada hasil yang cocok.</p>\n  </section>\n\n  <div id=\"hasil_rinci\" hidden>\n    <button id=\"kembali\" class=\"kembali\" type=\"button\">\u2190 Semua hasil</button>\n    <div id=\"berjalan\" class=\"kartu\" hidden>\n      <h2 id=\"berjalan_judul\"></h2>\n      <p id=\"berjalan_tahap\" class=\"redup\"></p>\n      <div class=\"batang\" role=\"progressbar\" aria-valuemin=\"0\" aria-valuemax=\"100\"><div id=\"batang_isi\"></div></div>\n      <p id=\"berjalan_persen\" class=\"redup\"></p>\n    </div>\n    <div id=\"gagal\" class=\"kartu\" hidden>\n      <h2 id=\"gagal_judul\"></h2>\n      <p class=\"galat\">Pemrosesan gagal.</p>\n      <pre id=\"gagal_pesan\"></pre>\n      <button id=\"gagal_hapus\" class=\"polos\" type=\"button\">Hapus dari hasil</button>\n    </div>\n    <div id=\"hasil\" hidden>\n      <div class=\"kartu\">\n        <div class=\"baris_judul\">\n          <h2 id=\"hasil_judul\"></h2>\n          <div class=\"aksi\">\n            <a id=\"unduh_csv\" class=\"tautan\" download>Unduh CSV</a>\n            <button id=\"hasil_hapus\" class=\"polos\" type=\"button\">Hapus</button>\n          </div>\n        </div>\n        <p id=\"hasil_info\" class=\"redup\"></p>\n        <video id=\"pemutar\" controls preload=\"metadata\"></video>\n        <p id=\"tanpa_video\" class=\"redup\" hidden>Video hasil tidak tersedia untuk pekerjaan ini.</p>\n      </div>\n      <div id=\"kartu_angka\" class=\"angka\"></div>\n      <div class=\"kartu\">\n        <h2>Kendaraan per rentang waktu</h2>\n        <div id=\"grafik\"></div>\n        <div id=\"legenda\" class=\"legenda\"></div>\n      </div>\n      <div class=\"kartu\">\n        <h2>Kendaraan yang dihitung</h2>\n        <p class=\"redup\">Klik baris untuk melompat ke saat kendaraan itu melintasi garis.</p>\n        <div class=\"gulir\">\n          <table>\n            <thead><tr><th>Waktu</th><th>ID</th><th>Kelas</th><th>Arah</th><th class=\"kanan\">Panjang (m)</th><th class=\"kanan\">Skor kelas</th></tr></thead>\n            <tbody id=\"tabel\"></tbody>\n          </table>\n        </div>\n        <p id=\"tabel_kosong\" class=\"redup\" hidden>Tidak ada kendaraan yang melintasi garis.</p>\n      </div>\n    </div>\n  </div>\n</main>\n<script src=\"aplikasi.js\"></script>\n</body>\n</html>\n", "frontend/gaya.css": ":root {\n  --latar: #f4f5f7; --kartu: #ffffff; --teks: #1b1f24; --redup: #5c6773; --garis: #dfe3e8;\n  --aksen: #1f5fbf; --aksen-teks: #ffffff; --galat: #b3261e; --peringatan-latar: #fff4d6; --peringatan-teks: #5c4400;\n  --pilih: #e8f0fc;\n}\n@media (prefers-color-scheme: dark) {\n  :root {\n    --latar: #13161a; --kartu: #1c2026; --teks: #e7eaee; --redup: #9aa5b1; --garis: #2e353e;\n    --aksen: #6ea8ff; --aksen-teks: #0c1420; --galat: #ff8a80; --peringatan-latar: #3a3112; --peringatan-teks: #f2dfa0;\n    --pilih: #24324a;\n  }\n}\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--latar); color: var(--teks);\n  font: 15px/1.5 system-ui, -apple-system, \"Segoe UI\", Roboto, \"Noto Sans\", sans-serif; }\nh1 { font-size: 20px; margin: 0; }\nh2 { font-size: 15px; margin: 0 0 10px; }\n.sub { margin: 2px 0 0; color: var(--redup); font-size: 13px; }\n.redup { color: var(--redup); font-size: 13px; margin: 6px 0; }\n.galat { color: var(--galat); font-size: 13px; margin: 8px 0 0; }\n.atas { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap;\n  padding: 14px 20px; background: var(--kartu); border-bottom: 1px solid var(--garis); }\n.lencana { font-size: 12px; color: var(--redup); border: 1px solid var(--garis); border-radius: 999px; padding: 3px 10px; }\n.peringatan { margin: 12px 20px 0; padding: 10px 14px; border-radius: 8px; font-size: 13px;\n  background: var(--peringatan-latar); color: var(--peringatan-teks); }\n.peringatan p { margin: 2px 0; }\n.tata { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 16px; padding: 16px 20px 40px; max-width: 1280px; margin: 0 auto; }\n@media (max-width: 820px) { .tata { grid-template-columns: minmax(0, 1fr); padding: 12px 16px 32px; } }\n.samping, .utama { display: flex; flex-direction: column; gap: 16px; min-width: 0; }\n#hasil { display: flex; flex-direction: column; gap: 16px; }\n#hasil[hidden] { display: none; }\n.kartu { background: var(--kartu); border: 1px solid var(--garis); border-radius: 10px; padding: 16px; min-width: 0; }\n.tengah { text-align: center; color: var(--redup); padding: 48px 16px; }\nlabel { display: block; font-size: 12px; color: var(--redup); margin: 10px 0 4px; }\nselect, input[type=number], input[type=file] { width: 100%; padding: 7px 8px; border: 1px solid var(--garis); border-radius: 6px;\n  background: var(--latar); color: var(--teks); font: inherit; font-size: 14px; }\ndetails { margin-top: 12px; }\nsummary { cursor: pointer; font-size: 13px; color: var(--redup); }\n.kisi2 { display: grid; grid-template-columns: 1fr 1fr; gap: 0 10px; }\nbutton { font: inherit; cursor: pointer; border-radius: 6px; }\n#tombol { width: 100%; margin-top: 14px; padding: 9px; border: 0; background: var(--aksen); color: var(--aksen-teks); font-weight: 600; }\n#tombol:disabled { opacity: .6; cursor: default; }\n.polos { background: none; border: 1px solid var(--garis); color: var(--teks); padding: 5px 10px; font-size: 13px; }\n.tautan { color: var(--aksen); font-size: 13px; text-decoration: none; }\n.tautan:hover { text-decoration: underline; }\n.riwayat { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; max-height: 340px; overflow-y: auto; }\n.riwayat button { width: 100%; text-align: left; background: none; border: 1px solid transparent; padding: 7px 8px; color: var(--teks); }\n.riwayat button:hover { border-color: var(--garis); }\n.riwayat button.aktif { background: var(--pilih); border-color: var(--garis); }\n.riwayat .nama { display: block; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.riwayat .ket { display: block; font-size: 12px; color: var(--redup); }\n.batang { height: 10px; background: var(--latar); border: 1px solid var(--garis); border-radius: 999px; overflow: hidden; margin-top: 10px; }\n#batang_isi { height: 100%; width: 0; background: var(--aksen); transition: width .4s; }\npre { white-space: pre-wrap; word-break: break-word; font-size: 12px; background: var(--latar); border: 1px solid var(--garis);\n  border-radius: 6px; padding: 10px; max-height: 260px; overflow: auto; }\n.baris_judul { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; }\n.baris_judul h2 { margin: 0; overflow-wrap: anywhere; }\n.aksi { display: flex; align-items: center; gap: 12px; }\nvideo { width: 100%; border-radius: 6px; background: #000; margin-top: 8px; aspect-ratio: 16 / 9; }\n.angka { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 12px; }\n.angka .kartu { padding: 12px 14px; }\n.angka .judul { font-size: 12px; color: var(--redup); display: flex; align-items: center; gap: 6px; }\n.angka .nilai { font-size: 28px; font-weight: 650; line-height: 1.2; font-variant-numeric: tabular-nums; }\n.titik { width: 10px; height: 10px; border-radius: 3px; display: inline-block; flex: none; border: 1px solid rgba(0,0,0,.25); }\n#grafik svg { width: 100%; height: auto; display: block; }\n#grafik text { fill: var(--redup); font-size: 11px; }\n#grafik .sumbu { stroke: var(--garis); }\n.legenda { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12px; color: var(--redup); margin-top: 6px; }\n.legenda span { display: inline-flex; align-items: center; gap: 5px; }\n.gulir { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; }\nth { text-align: left; color: var(--redup); font-weight: 500; font-size: 12px; padding: 6px 8px; border-bottom: 1px solid var(--garis); white-space: nowrap; }\ntd { padding: 7px 8px; border-bottom: 1px solid var(--garis); white-space: nowrap; }\ntbody tr { cursor: pointer; }\ntbody tr:hover { background: var(--pilih); }\n.kanan { text-align: right; }\ntd .titik { margin-right: 6px; vertical-align: baseline; }\n\n/* ---------- navigasi dan halaman ---------- */\n.nav { display: flex; gap: 4px; padding: 0 20px; background: var(--kartu); border-bottom: 1px solid var(--garis); overflow-x: auto; }\n.nav a { padding: 10px 14px; color: var(--redup); text-decoration: none; font-size: 14px; white-space: nowrap; border-bottom: 2px solid transparent; }\n.nav a:hover { color: var(--teks); }\n.nav a.aktif { color: var(--aksen); border-bottom-color: var(--aksen); font-weight: 600; }\n.halaman { max-width: 1280px; margin: 0 auto; padding: 16px 20px 40px; display: flex; flex-direction: column; gap: 16px; }\n.halaman[hidden] { display: none; }\n@media (max-width: 820px) { .halaman { padding: 12px 16px 32px; } .nav { padding: 0 8px; } }\n.dua { display: grid; grid-template-columns: 340px minmax(0, 1fr); gap: 16px; align-items: start; }\n@media (max-width: 900px) { .dua { grid-template-columns: minmax(0, 1fr); } }\n.kolom { display: flex; flex-direction: column; gap: 16px; min-width: 0; }\n.baris { display: flex; gap: 10px; align-items: end; flex-wrap: wrap; }\n.baris > div { flex: 1 1 140px; min-width: 0; }\ninput[type=text], input[type=date], input[type=search] { width: 100%; padding: 7px 8px; border: 1px solid var(--garis); border-radius: 6px;\n  background: var(--latar); color: var(--teks); font: inherit; font-size: 14px; }\ninput[type=range] { width: 100%; }\n.utamakan { padding: 8px 14px; border: 0; background: var(--aksen); color: var(--aksen-teks); font-weight: 600; }\n.utamakan:disabled { opacity: .6; cursor: default; }\n.status { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; }\n.lampu { width: 9px; height: 9px; border-radius: 50%; background: var(--redup); display: inline-block; }\n.lampu.hidup { background: #1a9c4b; }\n.jam { display: flex; gap: 6px; flex-wrap: wrap; margin: 8px 0 0; padding: 0; list-style: none; }\n.jam li { font-size: 12px; border: 1px solid var(--garis); border-radius: 999px; padding: 2px 9px; font-variant-numeric: tabular-nums; }\n.jam li.sudah { background: var(--pilih); }\ndl.rinci { display: grid; grid-template-columns: auto 1fr; gap: 4px 14px; margin: 0; font-size: 13px; }\ndl.rinci dt { color: var(--redup); }\ndl.rinci dd { margin: 0; }\n.tanda { font-size: 12px; border: 1px solid var(--garis); border-radius: 999px; padding: 1px 8px; white-space: nowrap; }\n.tanda.otomatis { background: var(--pilih); }\ntd .polos, td .tautan { margin-right: 6px; }\ntd.aksi_sel { white-space: nowrap; text-align: right; }\n#pratinjau_gbr { width: 100%; border-radius: 6px; background: #000; aspect-ratio: 16 / 9; display: block; }\n.geser { display: grid; grid-template-columns: 1fr 92px; gap: 8px; align-items: center; }\n.pilihan { display: flex; gap: 14px; font-size: 14px; margin: 6px 0; flex-wrap: wrap; }\n.pilihan label { display: inline-flex; align-items: center; gap: 6px; margin: 0; font-size: 14px; color: var(--teks); }\n.berhasil { color: #1a9c4b; font-size: 13px; margin: 8px 0 0; }\ntbody tr.statis { cursor: default; }\ntbody tr.statis:hover { background: none; }\n.kembali { background: none; border: 0; color: var(--aksen); padding: 0; font-size: 13px; }\ncode { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; background: var(--latar); border: 1px solid var(--garis);\n  border-radius: 4px; padding: 1px 5px; overflow-wrap: anywhere; }\n#hasil_rinci { display: flex; flex-direction: column; gap: 16px; }\n#hasil_rinci[hidden] { display: none; }\n#tabel_hasil tr, #tabel tr { cursor: pointer; }\n", "frontend/aplikasi.js": "// Antarmuka web: memanggil API server (backend/app.py) dan menampilkan empat halaman.\n\"use strict\";\n\nconst $ = (id) => document.getElementById(id);\nlet INFO = null;            // dari /api/info\nlet halaman = \"\";           // halaman yang sedang tampil\nlet pengatur = null;        // timer penyegaran halaman\nlet jobAktif = null;        // id job pada tampilan rinci\n\n// ---------------------------------------------------------------- alat kecil\nfunction el(tag, kelas, teks) {\n  const e = document.createElement(tag);\n  if (kelas) e.className = kelas;\n  if (teks !== undefined) e.textContent = teks;\n  return e;\n}\nfunction warna(kelas) {\n  const k = INFO.kelas.find((x) => x.nama === kelas);\n  return k ? k.warna : \"#999999\";\n}\nfunction jam(detik) {\n  const m = Math.floor(detik / 60), s = detik - m * 60;\n  return m + \":\" + (s < 10 ? \"0\" : \"\") + s.toFixed(1);\n}\nasync function api(jalur, opsi, mentah) {\n  const r = await fetch(jalur, opsi);\n  if (!r.ok) {\n    let pesan = \"Permintaan gagal (\" + r.status + \")\";\n    try { const j = await r.json(); if (j.detail) pesan = typeof j.detail === \"string\" ? j.detail : JSON.stringify(j.detail); } catch (e) { /* bukan JSON */ }\n    throw new Error(pesan);\n  }\n  return mentah ? r : r.json();\n}\nfunction isiPilihan(sel, daftar, nilai) {\n  const lama = nilai !== undefined ? nilai : sel.value;\n  sel.replaceChildren();\n  daftar.forEach(([v, t]) => sel.appendChild(new Option(t, v)));\n  if (daftar.some(([v]) => v === lama)) sel.value = lama;\n}\nfunction pesan(id, teks) {\n  const e = $(id);\n  e.textContent = teks || \"\";\n  e.hidden = !teks;\n}\nfunction namaNode(id) {\n  const n = INFO.node.find((x) => x.id === id);\n  return n ? n.nama : id;\n}\nconst LABEL = { antre: \"menunggu\", proses: \"diproses\", selesai: \"selesai\", gagal: \"gagal\" };\nconst JENIS = { otomatis: \"otomatis\", manual: \"manual\", contoh: \"contoh\" };\n\n// ---------------------------------------------------------------- navigasi\nfunction rute() {\n  const bagian = location.hash.replace(/^#\\/?/, \"\").split(\"/\");\n  const hal = [\"rekam\", \"kalibrasi\", \"proses\", \"hasil\"].includes(bagian[0]) ? bagian[0] : \"hasil\";\n  clearTimeout(pengatur);\n  halaman = hal;\n  for (const h of [\"rekam\", \"kalibrasi\", \"proses\", \"hasil\"]) $(\"hal_\" + h).hidden = h !== hal;\n  document.querySelectorAll(\".nav a\").forEach((a) => a.classList.toggle(\"aktif\", a.dataset.hal === hal));\n  ({ rekam: bukaRekam, kalibrasi: bukaKalibrasi, proses: bukaProses, hasil: () => bukaHasil(bagian[1]) })[hal]();\n}\nasync function muatInfo() {\n  INFO = await api(\"/api/info\");\n  const kotak = $(\"masalah\");\n  kotak.replaceChildren();\n  INFO.masalah.forEach((m) => kotak.appendChild(el(\"p\", \"\", m)));\n  kotak.hidden = !INFO.masalah.length;\n  const node = INFO.node.map((n) => [n.id, n.nama]);\n  for (const id of [\"rekam_node\", \"kal_node\", \"proses_node\"]) isiPilihan($(id), node);\n  isiPilihan($(\"cari_node\"), [[\"\", \"semua\"]].concat(node));\n}\n\n// ================================================================ Pengambilan video\nasync function bukaRekam() {\n  const j = INFO.jadwal;\n  $(\"jadwal_n\").textContent = j.video_per_hari + \" video\";\n  $(\"jadwal_durasi\").textContent = j.durasi_detik + \" detik\";\n  $(\"jadwal_rentang\").textContent = j.jam_mulai + \" \u2013 \" + j.jam_selesai;\n  $(\"jadwal_berkas\").textContent = INFO.berkas_setelan;\n  await segarkanRekam();\n}\nasync function segarkanRekam() {\n  if (halaman !== \"rekam\") return;\n  const node = $(\"rekam_node\").value;\n  try {\n    const [info, rekaman, minta] = await Promise.all([\n      api(\"/api/info\"), api(\"/api/rekaman?node=\" + encodeURIComponent(node)), api(\"/api/permintaan?node=\" + encodeURIComponent(node))]);\n    INFO.node = info.node;\n    const n = info.node.find((x) => x.id === node) || {};\n    $(\"node_lampu\").classList.toggle(\"hidup\", !!n.terhubung);\n    $(\"node_status\").textContent = n.terhubung ? \"Terhubung\" : (n.terakhir ? \"Tidak terhubung (terakhir \" + n.terakhir + \")\" : \"Belum pernah terhubung\");\n\n    const hariIni = new Date().toLocaleDateString(\"sv-SE\");\n    const sudah = rekaman.filter((r) => r.mode === \"otomatis\" && r.waktu.startsWith(hariIni)).length;\n    const ul = $(\"jadwal_jam\");\n    ul.replaceChildren();\n    INFO.jadwal.jam.forEach((t, i) => ul.appendChild(el(\"li\", i < sudah ? \"sudah\" : \"\", t)));\n\n    const pm = $(\"permintaan\");\n    pm.replaceChildren();\n    minta.slice(0, 5).forEach((r) => {\n      const li = el(\"li\");\n      li.appendChild(el(\"span\", \"ket\", r.dibuat + \" \u00b7 \" + r.durasi_detik + \" detik \u00b7 \" + r.status));\n      pm.appendChild(li);\n    });\n\n    const tb = $(\"tabel_rekaman\");\n    tb.replaceChildren();\n    $(\"rekaman_kosong\").hidden = rekaman.length > 0;\n    rekaman.forEach((r) => {\n      const tr = el(\"tr\", \"statis\");\n      tr.appendChild(el(\"td\", \"\", r.waktu));\n      const tdJenis = el(\"td\");\n      tdJenis.appendChild(el(\"span\", \"tanda \" + r.mode, JENIS[r.mode]));\n      tr.appendChild(tdJenis);\n      tr.appendChild(el(\"td\", \"kanan\", r.ukuran_mb.toFixed(1) + \" MB\"));\n      const terakhir = r.job[r.job.length - 1];\n      tr.appendChild(el(\"td\", \"\", terakhir ? LABEL[terakhir.status] : \"belum diproses\"));\n      const aksi = el(\"td\", \"aksi_sel\");\n      if (terakhir) {\n        const a = el(\"a\", \"tautan\", \"Lihat hasil\");\n        a.href = \"#/hasil/\" + terakhir.id;\n        aksi.appendChild(a);\n      }\n      const b = el(\"button\", \"polos\", terakhir ? \"Proses lagi\" : \"Proses\");\n      b.type = \"button\";\n      b.addEventListener(\"click\", () => { sessionStorage.setItem(\"pilih_sumber\", r.sumber); location.hash = \"#/proses\"; });\n      aksi.appendChild(b);\n      const h = el(\"button\", \"polos\", \"Hapus\");\n      h.type = \"button\";\n      h.addEventListener(\"click\", async () => {\n        if (!confirm(\"Hapus rekaman \" + r.waktu + \"?\")) return;\n        try { await api(\"/api/rekaman?sumber=\" + encodeURIComponent(r.sumber), { method: \"DELETE\" }); } catch (e) { alert(e.message); }\n        segarkanRekam();\n      });\n      aksi.appendChild(h);\n      tr.appendChild(aksi);\n      tb.appendChild(tr);\n    });\n  } catch (e) { /* server sedang tidak terjangkau; coba lagi */ }\n  clearTimeout(pengatur);\n  pengatur = setTimeout(segarkanRekam, 3000);\n}\n$(\"rekam_node\").addEventListener(\"change\", segarkanRekam);\n$(\"form_rekam\").addEventListener(\"submit\", async (ev) => {\n  ev.preventDefault();\n  pesan(\"rekam_pesan\", \"\");\n  const data = new FormData();\n  data.append(\"durasi\", $(\"rekam_durasi\").value);\n  try { await api(\"/api/kamera/\" + encodeURIComponent($(\"rekam_node\").value) + \"/rekam\", { method: \"POST\", body: data }); }\n  catch (e) { pesan(\"rekam_pesan\", e.message); }\n  segarkanRekam();\n});\n$(\"form_unggah\").addEventListener(\"submit\", async (ev) => {\n  ev.preventDefault();\n  pesan(\"unggah_pesan\", \"\");\n  if (!$(\"unggah_berkas\").files.length) { pesan(\"unggah_pesan\", \"Pilih berkas video dulu.\"); return; }\n  const data = new FormData();\n  data.append(\"node\", $(\"rekam_node\").value);\n  data.append(\"berkas\", $(\"unggah_berkas\").files[0]);\n  try { await api(\"/api/rekaman\", { method: \"POST\", body: data }); $(\"unggah_berkas\").value = \"\"; }\n  catch (e) { pesan(\"unggah_pesan\", e.message); }\n  segarkanRekam();\n});\n\n// ================================================================ Kalibrasi kamera\nconst KUNCI_KAL = [\"PITCH_DEG\", \"CAM_HEIGHT_M\", \"FOCAL_PX\", \"LINE_Y_DEFAULT_M\", \"LINE_Y_AWAY_M\", \"MEDIAN_X_M\", \"LANE_HALF_WIDTH_M\", \"MAX_TRACK_DEPTH_M\"];\nlet tundaPratinjau = null, nomorPratinjau = 0;\n\nasync function daftarSumber(node) {\n  const rekaman = await api(\"/api/rekaman\" + (node ? \"?node=\" + encodeURIComponent(node) : \"\"));\n  return rekaman.map((r) => [r.sumber, r.waktu + \" \u00b7 \" + namaNode(r.node) + \" \u00b7 \" + JENIS[r.mode]])\n    .concat(INFO.contoh.map((c) => [\"contoh/\" + c, \"contoh \u00b7 \" + c]));\n}\nasync function bukaKalibrasi() {\n  await muatProfil();\n}\nasync function muatProfil() {\n  pesan(\"kal_pesan\", \"\"); pesan(\"kal_ok\", \"\");\n  const node = $(\"kal_node\").value;\n  isiPilihan($(\"kal_sumber\"), await daftarSumber(node));\n  const p = await api(\"/api/kamera/\" + encodeURIComponent(node) + \"/profil\");\n  KUNCI_KAL.forEach((k) => { $(k).value = p[k]; });\n  document.querySelectorAll(\"input[data-untuk]\").forEach((r) => { r.value = $(r.dataset.untuk).value; });\n  document.querySelectorAll(\"input[name=mode]\").forEach((r) => { r.checked = r.value === p.mode; });\n  $(\"xml\").value = \"\";\n  $(\"kal_xml_ket\").textContent = p.ada_xml ? \"Berkas kalibrasi tersimpan: \" + p.CALIB_XML : \"Belum ada berkas kalibrasi tersimpan untuk node ini.\";\n  $(\"kal_tersimpan\").textContent = p.tersimpan ? \"Terakhir disimpan \" + p.tersimpan : \"Belum pernah disimpan (memakai nilai bawaan pipeline).\";\n  tampilMode();\n  pratinjau();\n}\nfunction tampilMode() {\n  const xml = document.querySelector(\"input[name=mode]:checked\").value === \"xml\";\n  $(\"kal_nilai\").hidden = xml;\n  $(\"kal_xml\").hidden = !xml;\n}\nfunction formulirKalibrasi() {\n  const data = new FormData();\n  KUNCI_KAL.forEach((k) => data.append(k, $(k).value));\n  data.append(\"mode\", document.querySelector(\"input[name=mode]:checked\").value);\n  if ($(\"xml\").files.length) data.append(\"xml\", $(\"xml\").files[0]);\n  return data;\n}\nfunction pratinjau() {\n  clearTimeout(tundaPratinjau);\n  tundaPratinjau = setTimeout(async () => {\n    if (!$(\"kal_sumber\").value) { pesan(\"pratinjau_pesan\", \"Belum ada video untuk pratinjau. Rekam atau unggah video dulu.\"); return; }\n    const nomor = ++nomorPratinjau;\n    const data = formulirKalibrasi();\n    data.append(\"sumber\", $(\"kal_sumber\").value);\n    data.append(\"posisi\", $(\"kal_posisi\").value);\n    try {\n      const r = await api(\"/api/kamera/\" + encodeURIComponent($(\"kal_node\").value) + \"/pratinjau\", { method: \"POST\", body: data }, true);\n      const blob = await r.blob();\n      if (nomor !== nomorPratinjau) return;          // sudah ada permintaan yang lebih baru\n      const lama = $(\"pratinjau_gbr\").src;\n      $(\"pratinjau_gbr\").src = URL.createObjectURL(blob);\n      if (lama.startsWith(\"blob:\")) URL.revokeObjectURL(lama);\n      pesan(\"pratinjau_pesan\", \"\");\n    } catch (e) { if (nomor === nomorPratinjau) pesan(\"pratinjau_pesan\", e.message); }\n  }, 250);\n}\n$(\"kal_node\").addEventListener(\"change\", muatProfil);\n$(\"form_kal\").addEventListener(\"input\", (ev) => {\n  const t = ev.target;\n  if (t.dataset.untuk) $(t.dataset.untuk).value = t.value;                       // penggeser -> angka\n  const geser = document.querySelector('input[data-untuk=\"' + t.id + '\"]');\n  if (geser) geser.value = t.value;                                              // angka -> penggeser\n  if (t.name === \"mode\") tampilMode();\n  pesan(\"kal_ok\", \"\");\n  pratinjau();\n});\n$(\"form_kal\").addEventListener(\"submit\", async (ev) => {\n  ev.preventDefault();\n  pesan(\"kal_pesan\", \"\"); pesan(\"kal_ok\", \"\");\n  try {\n    const p = await api(\"/api/kamera/\" + encodeURIComponent($(\"kal_node\").value) + \"/profil\", { method: \"POST\", body: formulirKalibrasi() });\n    await muatInfo();\n    await muatProfil();\n    pesan(\"kal_ok\", \"Profil tersimpan (\" + p.tersimpan + \"). Berlaku untuk video yang diproses setelah ini.\");\n  } catch (e) { pesan(\"kal_pesan\", e.message); }\n});\n\n// ================================================================ Proses\nasync function bukaProses() {\n  pesan(\"galat_form\", \"\");\n  isiPilihan($(\"proses_model\"), INFO.model.map((m) => [m, m]));\n  if (!$(\"conf\").value) { $(\"conf\").value = INFO.bawaan.conf; $(\"conf_low\").value = INFO.bawaan.conf_low; }\n  const pilih = sessionStorage.getItem(\"pilih_sumber\");\n  sessionStorage.removeItem(\"pilih_sumber\");\n  isiPilihan($(\"proses_sumber\"), await daftarSumber(\"\"), pilih || undefined);\n  ikutiNode();\n  await segarkanAntrean();\n}\nfunction ikutiNode() {                       // rekaman -> profil node pemiliknya\n  const b = $(\"proses_sumber\").value.split(\"/\");\n  if (b[0] === \"rekaman\" && INFO.node.some((n) => n.id === b[1])) $(\"proses_node\").value = b[1];\n}\n$(\"proses_sumber\").addEventListener(\"change\", ikutiNode);\nasync function segarkanAntrean() {\n  if (halaman !== \"proses\") return;\n  try {\n    const jobs = (await api(\"/api/jobs\")).filter((j) => j.status === \"antre\" || j.status === \"proses\");\n    const tb = $(\"tabel_antrean\");\n    tb.replaceChildren();\n    $(\"antrean_kosong\").hidden = jobs.length > 0;\n    jobs.reverse().forEach((j) => {\n      const tr = el(\"tr\");\n      tr.appendChild(el(\"td\", \"\", j.nama_video));\n      tr.appendChild(el(\"td\", \"\", j.model));\n      tr.appendChild(el(\"td\", \"\", j.status === \"proses\" ? j.tahap : LABEL[j.status]));\n      tr.appendChild(el(\"td\", \"kanan\", Math.round((j.progres || 0) * 100) + \"%\"));\n      tr.addEventListener(\"click\", () => { location.hash = \"#/hasil/\" + j.id; });\n      tb.appendChild(tr);\n    });\n  } catch (e) { /* coba lagi */ }\n  clearTimeout(pengatur);\n  pengatur = setTimeout(segarkanAntrean, 1500);\n}\n$(\"form_proses\").addEventListener(\"submit\", async (ev) => {\n  ev.preventDefault();\n  pesan(\"galat_form\", \"\");\n  if (!$(\"proses_sumber\").value) { pesan(\"galat_form\", \"Belum ada video. Rekam atau unggah video di halaman Pengambilan video.\"); return; }\n  const data = new FormData();\n  data.append(\"sumber\", $(\"proses_sumber\").value);\n  data.append(\"node\", $(\"proses_node\").value);\n  data.append(\"model\", $(\"proses_model\").value);\n  data.append(\"conf\", $(\"conf\").value);\n  data.append(\"conf_low\", $(\"conf_low\").value);\n  $(\"tombol\").disabled = true;\n  try {\n    const j = await api(\"/api/jobs\", { method: \"POST\", body: data });\n    location.hash = \"#/hasil/\" + j.id;\n  } catch (e) { pesan(\"galat_form\", e.message); }\n  finally { $(\"tombol\").disabled = false; }\n});\n\n// ================================================================ Hasil\nasync function bukaHasil(id) {\n  jobAktif = id || null;\n  $(\"hasil_daftar\").hidden = !!id;\n  $(\"hasil_rinci\").hidden = !id;\n  if (id) await segarkanRinci(); else await segarkanDaftar();\n}\nasync function segarkanDaftar() {\n  if (halaman !== \"hasil\" || jobAktif) return;\n  try {\n    const jobs = await api(\"/api/jobs\");\n    const nama = $(\"cari_nama\").value.trim().toLowerCase(), tgl = $(\"cari_tanggal\").value, node = $(\"cari_node\").value;\n    const cocok = jobs.filter((j) => (!nama || j.nama_video.toLowerCase().includes(nama)) &&\n      (!tgl || (j.waktu_video || \"\").startsWith(tgl)) && (!node || j.node === node))\n      .sort((x, y) => (y.waktu_video || y.dibuat).localeCompare(x.waktu_video || x.dibuat));   // rekaman terbaru di atas\n    $(\"kepala_kelas\").textContent = INFO.kelas.map((k) => k.nama).join(\" / \");\n    const tb = $(\"tabel_hasil\");\n    tb.replaceChildren();\n    $(\"hasil_kosong\").hidden = cocok.length > 0;\n    cocok.forEach((j) => {\n      const tr = el(\"tr\");\n      tr.appendChild(el(\"td\", \"\", j.waktu_video || j.dibuat));\n      tr.appendChild(el(\"td\", \"\", j.nama_video));\n      tr.appendChild(el(\"td\", \"\", namaNode(j.node || \"\")));\n      tr.appendChild(el(\"td\", \"\", j.model || \"-\"));\n      const tdJenis = el(\"td\");\n      tdJenis.appendChild(el(\"span\", \"tanda \" + (j.pemicu || \"\"), JENIS[j.pemicu] || \"-\"));\n      tr.appendChild(tdJenis);\n      tr.appendChild(el(\"td\", \"\", j.status === \"proses\" ? \"diproses \" + Math.round((j.progres || 0) * 100) + \"%\" : LABEL[j.status]));\n      tr.appendChild(el(\"td\", \"kanan\", j.status === \"selesai\" ? String(j.total) : \"-\"));\n      tr.appendChild(el(\"td\", \"\", j.status === \"selesai\" && j.per_kelas ? INFO.kelas.map((k) => j.per_kelas[k.nama] || 0).join(\" / \") : \"-\"));\n      tr.addEventListener(\"click\", () => { location.hash = \"#/hasil/\" + j.id; });\n      tb.appendChild(tr);\n    });\n  } catch (e) { /* coba lagi */ }\n  clearTimeout(pengatur);\n  pengatur = setTimeout(segarkanDaftar, 3000);\n}\nfor (const id of [\"cari_nama\", \"cari_tanggal\", \"cari_node\"]) $(id).addEventListener(\"input\", segarkanDaftar);\n$(\"kembali\").addEventListener(\"click\", () => { location.hash = \"#/hasil\"; });\n\nfunction tampilRinci(nama) {\n  for (const n of [\"berjalan\", \"gagal\", \"hasil\"]) $(n).hidden = n !== nama;\n}\nasync function segarkanRinci() {\n  if (halaman !== \"hasil\" || !jobAktif) return;\n  let j;\n  try { j = await api(\"/api/jobs/\" + jobAktif); }\n  catch (e) { location.hash = \"#/hasil\"; return; }\n  if (j.status === \"antre\" || j.status === \"proses\") {\n    tampilRinci(\"berjalan\");\n    $(\"berjalan_judul\").textContent = j.nama_video;\n    $(\"berjalan_tahap\").textContent = j.tahap;\n    const p = Math.round((j.progres || 0) * 100);\n    $(\"batang_isi\").style.width = p + \"%\";\n    $(\"batang_isi\").parentElement.setAttribute(\"aria-valuenow\", p);\n    $(\"berjalan_persen\").textContent = p + \"%\" + (j.frame_total ? \" dari \" + j.frame_total + \" frame\" : \"\");\n    clearTimeout(pengatur);\n    pengatur = setTimeout(segarkanRinci, 1000);\n  } else if (j.status === \"gagal\") {\n    tampilRinci(\"gagal\");\n    $(\"gagal_judul\").textContent = j.nama_video;\n    $(\"gagal_pesan\").textContent = j.pesan || \"(tidak ada keterangan)\";\n  } else {\n    gambarHasil(j);\n    tampilRinci(\"hasil\");\n  }\n}\nasync function hapusAktif() {\n  if (!jobAktif || !confirm(\"Hapus hasil ini? Video hasil dan lognya ikut terhapus. Rekaman aslinya tidak dihapus.\")) return;\n  try { await api(\"/api/jobs/\" + jobAktif, { method: \"DELETE\" }); } catch (e) { alert(e.message); return; }\n  location.hash = \"#/hasil\";\n}\n$(\"hasil_hapus\").addEventListener(\"click\", hapusAktif);\n$(\"gagal_hapus\").addEventListener(\"click\", hapusAktif);\n\nfunction kartuAngka(judul, nilai, warnaTitik) {\n  const k = el(\"div\", \"kartu\");\n  const j = el(\"div\", \"judul\");\n  if (warnaTitik) { const t = el(\"span\", \"titik\"); t.style.background = warnaTitik; j.appendChild(t); }\n  j.appendChild(document.createTextNode(judul));\n  k.appendChild(j);\n  k.appendChild(el(\"div\", \"nilai\", String(nilai)));\n  return k;\n}\nfunction gambarHasil(j) {\n  const r = j.ringkasan;\n  const dasar = \"/api/jobs/\" + j.id + \"/berkas/\";\n  $(\"hasil_judul\").textContent = j.nama_video;\n  const g = j.garis || {};\n  $(\"hasil_info\").textContent = \"Direkam \" + (j.waktu_video || \"-\") + \" \u00b7 \" + namaNode(j.node || \"\") + \" \u00b7 model \" + (j.model || \"-\") +\n    \" \u00b7 durasi \" + jam(r.durasi_detik) + \" \u00b7 \" + j.frame_total + \" frame \u00b7 diproses \" + j.dibuat + \" dalam \" + j.lama_detik + \" detik\" +\n    (g.mendekat !== undefined ? \" \u00b7 garis \" + g.mendekat + \" m / \" + g.menjauh + \" m\" : \"\");\n  $(\"unduh_csv\").href = dasar + \"counting_log.csv\";\n  const v = $(\"pemutar\");\n  v.hidden = !j.ada_video;\n  $(\"tanpa_video\").hidden = !!j.ada_video;\n  if (j.ada_video && v.dataset.id !== j.id) { v.src = dasar + \"hasil.mp4\"; v.dataset.id = j.id; }\n\n  const angka = $(\"kartu_angka\");\n  angka.replaceChildren(kartuAngka(\"Total\", r.total));\n  INFO.kelas.forEach((k) => angka.appendChild(kartuAngka(k.nama, r.per_kelas[k.nama] || 0, k.warna)));\n  if (r.ada_arah) {\n    angka.appendChild(kartuAngka(\"Mendekat\", r.per_arah.mendekat));\n    angka.appendChild(kartuAngka(\"Menjauh\", r.per_arah.menjauh));\n  }\n  gambarGrafik(r);\n\n  const tb = $(\"tabel\");\n  tb.replaceChildren();\n  $(\"tabel_kosong\").hidden = r.kendaraan.length > 0;\n  r.kendaraan.forEach((k) => {\n    const tr = el(\"tr\");\n    tr.appendChild(el(\"td\", \"\", jam(k.detik)));\n    tr.appendChild(el(\"td\", \"\", String(k.id)));\n    const td = el(\"td\");\n    const t = el(\"span\", \"titik\"); t.style.background = warna(k.kelas);\n    td.appendChild(t); td.appendChild(document.createTextNode(k.kelas));\n    tr.appendChild(td);\n    tr.appendChild(el(\"td\", \"\", r.ada_arah ? k.arah : \"-\"));\n    tr.appendChild(el(\"td\", \"kanan\", k.panjang_m.toFixed(2)));\n    tr.appendChild(el(\"td\", \"kanan\", k.skor === null ? \"-\" : k.skor.toFixed(2)));\n    tr.addEventListener(\"click\", () => {\n      if (!j.ada_video) return;\n      v.currentTime = Math.max(0, k.detik - 1);\n      v.play().catch(() => {});\n      v.scrollIntoView({ behavior: \"smooth\", block: \"center\" });\n    });\n    tb.appendChild(tr);\n  });\n}\n\n// grafik batang bertumpuk (SVG), satu batang per rentang waktu\nfunction gambarGrafik(r) {\n  const NS = \"http://www.w3.org/2000/svg\";\n  const W = 720, H = 220, kiri = 30, bawah = 24, atas = 10;\n  const svg = document.createElementNS(NS, \"svg\");\n  svg.setAttribute(\"viewBox\", \"0 0 \" + W + \" \" + H);\n  svg.setAttribute(\"role\", \"img\");\n  svg.setAttribute(\"aria-label\", \"Jumlah kendaraan per rentang waktu\");\n  const buat = (tag, attr, teks) => {\n    const e = document.createElementNS(NS, tag);\n    for (const k in attr) e.setAttribute(k, attr[k]);\n    if (teks !== undefined) e.textContent = teks;\n    svg.appendChild(e);\n    return e;\n  };\n  const data = r.per_waktu;\n  const jumlah = data.map((d) => INFO.kelas.reduce((a, k) => a + (d[k.nama] || 0), 0));\n  const maks = Math.max(1, ...jumlah);\n  const tinggi = H - bawah - atas, lebar = (W - kiri - 8) / data.length;\n  const langkahY = Math.max(1, Math.ceil(maks / 4));\n  for (let y = 0; y <= maks; y += langkahY) {\n    const py = atas + tinggi - (y / maks) * tinggi;\n    buat(\"line\", { x1: kiri, x2: W - 8, y1: py, y2: py, class: \"sumbu\" });\n    buat(\"text\", { x: kiri - 6, y: py + 4, \"text-anchor\": \"end\" }, String(y));\n  }\n  data.forEach((d, i) => {\n    let dasar = atas + tinggi;\n    const x = kiri + i * lebar + lebar * 0.18, w = lebar * 0.64;\n    INFO.kelas.forEach((k) => {\n      const n = d[k.nama] || 0;\n      if (!n) return;\n      const h = (n / maks) * tinggi;\n      dasar -= h;\n      const rect = buat(\"rect\", { x: x, y: dasar, width: w, height: h, fill: k.warna, rx: 2 });\n      const judul = document.createElementNS(NS, \"title\");\n      judul.textContent = jam(d.mulai) + \" \u2013 \" + jam(d.mulai + r.langkah_detik) + \": \" + n + \" \" + k.nama;\n      rect.appendChild(judul);\n    });\n    if (data.length <= 14 || i % 2 === 0) buat(\"text\", { x: x + w / 2, y: H - 7, \"text-anchor\": \"middle\" }, jam(d.mulai).replace(\".0\", \"\"));\n  });\n  $(\"grafik\").replaceChildren(svg);\n  const leg = $(\"legenda\");\n  leg.replaceChildren();\n  INFO.kelas.forEach((k) => {\n    const s = el(\"span\");\n    const t = el(\"span\", \"titik\"); t.style.background = k.warna;\n    s.appendChild(t); s.appendChild(document.createTextNode(k.nama));\n    leg.appendChild(s);\n  });\n  leg.appendChild(el(\"span\", \"\", \"Tiap batang = \" + r.langkah_detik + \" detik\"));\n}\n\n// ---------------------------------------------------------------- mulai\nwindow.addEventListener(\"hashchange\", rute);\nmuatInfo().then(rute).catch((e) => {\n  const kotak = $(\"masalah\");\n  kotak.appendChild(el(\"p\", \"\", \"Tidak bisa menghubungi server: \" + e.message));\n  kotak.hidden = false;\n});\n", "node/node_kamera.py": "#!/usr/bin/env python3\n\"\"\"\nnode_kamera.py - program untuk Raspberry Pi (node kamera). Hanya memakai pustaka bawaan Python.\n\nTugasnya: tiap beberapa detik bertanya ke server \"ada tugas apa?\", lalu\n  - merekam pada jam-jam jadwal otomatis yang diberikan server, dan\n  - merekam saat ada permintaan manual dari halaman web,\nkemudian mengirim videonya ke server. Rekaman otomatis langsung diproses server;\nrekaman manual hanya disimpan.\n\nDi Raspberry Pi (kamera asli):\n    python3 node_kamera.py --server http://ALAMAT_SERVER:8000 --node kamera1 --token TOKEN\nUji tanpa kamera (kamera tiruan dari berkas video), di komputer mana pun:\n    python3 node_kamera.py --server http://127.0.0.1:8000 --node kamera1 --token TOKEN \\\\\n        --sumber ~/projects/video_uji/uji_val_720p.mp4\n\nTOKEN ada di antarmuka/data/setelan.json (\"token_node\") pada server.\nPerintah rekam kamera asli bisa diganti dengan --perintah; {ms} = durasi milidetik,\n{detik} = durasi detik, {keluar} = berkas keluaran. Bawaannya untuk Raspberry Pi OS (rpicam-vid).\n\"\"\"\nimport argparse\nimport http.client\nimport json\nimport os\nimport shlex\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport time\nimport urllib.parse\nimport uuid\n\nPERINTAH_BAWAAN = \"rpicam-vid -t {ms} --width 1280 --height 720 --framerate 25 --codec libav -o {keluar} -n\"\n\n\ndef log(*a):\n    print(time.strftime(\"[%H:%M:%S]\"), *a, flush=True)\n\n\nclass Server:\n    def __init__(self, url, node, token):\n        u = urllib.parse.urlparse(url)\n        self.https = u.scheme == \"https\"\n        self.host, self.port = u.hostname, u.port or (443 if self.https else 80)\n        self.node, self.token = node, token\n\n    def _sambung(self, timeout):\n        kelas = http.client.HTTPSConnection if self.https else http.client.HTTPConnection\n        return kelas(self.host, self.port, timeout=timeout)\n\n    def tugas(self):\n        c = self._sambung(15)\n        c.request(\"GET\", \"/api/node/%s/tugas\" % self.node, headers={\"X-Token\": self.token})\n        r = c.getresponse()\n        isi = r.read()\n        c.close()\n        if r.status != 200:\n            raise RuntimeError(\"server menjawab %d: %s\" % (r.status, isi[:200].decode(errors=\"replace\")))\n        return json.loads(isi)\n\n    def unggah(self, jalur, bidang):\n        \"\"\"Kirim berkas sebagai multipart/form-data tanpa memuat seluruh berkas ke memori.\"\"\"\n        batas = uuid.uuid4().hex\n        kepala = b\"\"\n        for k, v in bidang.items():\n            kepala += (\"--%s\\r\\nContent-Disposition: form-data; name=\\\"%s\\\"\\r\\n\\r\\n%s\\r\\n\" % (batas, k, v)).encode()\n        kepala += (\"--%s\\r\\nContent-Disposition: form-data; name=\\\"berkas\\\"; filename=\\\"rekaman.mp4\\\"\\r\\n\"\n                   \"Content-Type: video/mp4\\r\\n\\r\\n\" % batas).encode()\n        ekor = (\"\\r\\n--%s--\\r\\n\" % batas).encode()\n        panjang = len(kepala) + os.path.getsize(jalur) + len(ekor)\n        c = self._sambung(600)\n        c.putrequest(\"POST\", \"/api/node/%s/rekaman\" % self.node)\n        c.putheader(\"X-Token\", self.token)\n        c.putheader(\"Content-Type\", \"multipart/form-data; boundary=\" + batas)\n        c.putheader(\"Content-Length\", str(panjang))\n        c.endheaders()\n        c.send(kepala)\n        with open(jalur, \"rb\") as f:\n            while True:\n                potong = f.read(256 * 1024)\n                if not potong:\n                    break\n                c.send(potong)\n        c.send(ekor)\n        r = c.getresponse()\n        isi = r.read()\n        c.close()\n        if r.status != 200:\n            raise RuntimeError(\"unggah ditolak (%d): %s\" % (r.status, isi[:300].decode(errors=\"replace\")))\n        return json.loads(isi)\n\n\nclass Kamera:\n    def __init__(self, sumber, perintah, folder):\n        self.sumber, self.perintah, self.folder = sumber, perintah, folder\n        self.geser = 0.0            # posisi di berkas sumber (kamera tiruan)\n\n    def rekam(self, detik):\n        keluar = os.path.join(self.folder, \"rekaman_%d.mp4\" % int(time.time()))\n        if self.sumber:\n            self._tiruan(detik, keluar)\n        else:\n            cmd = self.perintah.format(ms=int(detik * 1000), detik=int(detik), keluar=shlex.quote(keluar))\n            log(\"merekam %d detik:\" % detik, cmd)\n            subprocess.run(cmd, shell=True, check=True, timeout=detik + 120)\n        if not os.path.exists(keluar) or os.path.getsize(keluar) == 0:\n            raise RuntimeError(\"perekaman tidak menghasilkan berkas\")\n        return keluar\n\n    def _tiruan(self, detik, keluar):\n        \"\"\"Potong `detik` dari berkas sumber, lalu maju; kembali ke awal bila habis.\"\"\"\n        if not shutil.which(\"ffmpeg\"):\n            raise RuntimeError(\"kamera tiruan memerlukan ffmpeg (sudo apt install ffmpeg)\")\n        log(\"kamera tiruan: memotong %d detik dari %s (mulai %.0f s)\" % (detik, os.path.basename(self.sumber), self.geser))\n        cmd = [\"ffmpeg\", \"-y\", \"-loglevel\", \"error\", \"-stream_loop\", \"-1\", \"-ss\", \"%.2f\" % self.geser, \"-i\", self.sumber,\n               \"-t\", str(detik), \"-an\", \"-c:v\", \"libx264\", \"-preset\", \"veryfast\", \"-pix_fmt\", \"yuv420p\", keluar]\n        subprocess.run(cmd, check=True, timeout=detik * 10 + 120)\n        self.geser = (self.geser + detik) % max(1.0, self._durasi())\n\n    def _durasi(self):\n        try:\n            out = subprocess.run([\"ffprobe\", \"-v\", \"error\", \"-show_entries\", \"format=duration\", \"-of\", \"csv=p=0\",\n                                  self.sumber], capture_output=True, text=True, timeout=30).stdout\n            return float(out.strip())\n        except Exception:\n            return 3600.0\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=\"Node kamera: merekam dan mengirim video ke server\")\n    ap.add_argument(\"--server\", required=True, help=\"alamat server, mis. http://192.168.1.10:8000\")\n    ap.add_argument(\"--node\", required=True, help=\"id node, harus terdaftar di setelan.json server\")\n    ap.add_argument(\"--token\", required=True, help=\"token_node dari setelan.json server\")\n    ap.add_argument(\"--sumber\", default=None, help=\"berkas video sebagai kamera tiruan (untuk uji)\")\n    ap.add_argument(\"--perintah\", default=PERINTAH_BAWAAN, help=\"perintah rekam kamera asli\")\n    ap.add_argument(\"--jeda\", type=float, default=5.0, help=\"detik antara tiap pertanyaan ke server\")\n    ap.add_argument(\"--toleransi\", type=int, default=300, help=\"detik terlambat yang masih boleh untuk jadwal\")\n    ap.add_argument(\"--sekali\", action=\"store_true\", help=\"tanya server satu kali lalu berhenti (untuk uji)\")\n    a = ap.parse_args()\n\n    sumber = os.path.expanduser(a.sumber) if a.sumber else None\n    if sumber and not os.path.exists(sumber):\n        sys.exit(\"Berkas sumber tidak ada: \" + sumber)\n    folder = tempfile.mkdtemp(prefix=\"node_kamera_\")\n    server, kamera = Server(a.server, a.node, a.token), Kamera(sumber, a.perintah, folder)\n    log(\"node %s -> %s (%s)\" % (a.node, a.server, \"kamera tiruan\" if sumber else \"kamera asli\"))\n\n    def rekam_dan_kirim(detik, bidang):\n        jalur = None\n        try:\n            jalur = kamera.rekam(detik)\n            hasil = server.unggah(jalur, bidang)\n            log(\"terkirim:\", hasil)\n        except Exception as e:\n            log(\"GAGAL:\", e)\n        finally:\n            if jalur and os.path.exists(jalur):\n                os.remove(jalur)\n\n    while True:\n        try:\n            t = server.tugas()\n        except Exception as e:\n            log(\"tidak bisa mengambil tugas dari server:\", e)\n            if a.sekali:\n                sys.exit(1)\n            time.sleep(a.jeda)\n            continue\n        for m in t[\"manual\"]:\n            log(\"permintaan manual\", m[\"id\"], \"%d detik\" % m[\"durasi_detik\"])\n            rekam_dan_kirim(m[\"durasi_detik\"], {\"mode\": \"manual\", \"id_permintaan\": m[\"id\"]})\n        sekarang = time.localtime()\n        detik_hari = sekarang.tm_hour * 3600 + sekarang.tm_min * 60 + sekarang.tm_sec\n        for jam in t[\"jadwal\"]:\n            mulai = int(jam[:2]) * 3600 + int(jam[3:5]) * 60\n            if jam not in t[\"sudah\"] and mulai <= detik_hari <= mulai + a.toleransi:\n                log(\"jadwal otomatis\", jam)\n                rekam_dan_kirim(t[\"durasi_detik\"], {\"mode\": \"otomatis\", \"slot\": jam})\n                break                       # tanya server lagi sebelum jadwal berikutnya\n        if a.sekali:\n            break\n        time.sleep(a.jeda)\n\n\nif __name__ == \"__main__\":\n    main()\n"}''')
BLOK_PROFIL = json.loads(r'''"\n# ----------------------------------------------------------------------\n# Profil kamera dari antarmuka web. Bila variabel lingkungan PROFIL_KAMERA berisi jalur berkas\n# JSON, nilai kalibrasi dan garis hitung di atas ditimpa oleh isi berkas itu (per kamera/node).\n# Tanpa variabel itu, config ini berlaku apa adanya.\n# ----------------------------------------------------------------------\nimport os as _os\n_profil_kamera = _os.environ.get(\"PROFIL_KAMERA\")\nif _profil_kamera and _os.path.exists(_profil_kamera):\n    import json as _json\n    with open(_profil_kamera, encoding=\"utf-8\") as _f:\n        for _k, _v in _json.load(_f).items():\n            if _k in (\"CALIB_XML\", \"PITCH_DEG\", \"CAM_HEIGHT_M\", \"FOCAL_PX\", \"LANE_HALF_WIDTH_M\",\n                      \"MAX_TRACK_DEPTH_M\", \"LINE_Y_DEFAULT_M\", \"LINE_Y_AWAY_M\", \"MEDIAN_X_M\"):\n                globals()[_k] = _v\n"''')

